-- ============================================================

-- MHIDA English course — curriculum seed (30 weeks, CEFR A1->B1)

-- 'Open Frequency English' for MHIDA doctor members.

-- Run AFTER migration10_course.sql. Safe to re-run: upserts by

-- (week, lesson_no), so existing rows are updated in place

-- (e.g. to add video_url to weeks 1-10) and new weeks are inserted.

-- ============================================================

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (1, 1, 'Hello! Greetings & Introductions', 'Мэндчилгээ ба танилцах', 'https://www.youtube.com/watch?v=WR9_nsLyaEY', '{"objectives": ["Greet people formally and informally", "Introduce yourself with your name and job", "Say goodbye politely", "Use ''I am'' and ''My name is'' correctly"], "dialogue": [{"speaker": "Dr. Bat", "en": "Good morning! My name is Bat.", "mn": "Өглөөний мэнд! Намайг Бат гэдэг."}, {"speaker": "Dr. Sara", "en": "Good morning, Bat. I am Sara. Nice to meet you.", "mn": "Өглөөний мэнд, Бат. Би Сара. Танилцахад таатай байна."}, {"speaker": "Dr. Bat", "en": "Nice to meet you too. Are you a doctor?", "mn": "Танилцахад таатай байна. Та эмч үү?"}, {"speaker": "Dr. Sara", "en": "Yes, I am. I am an insurance doctor.", "mn": "Тийм ээ. Би даатгалын эмч."}, {"speaker": "Dr. Bat", "en": "Great! Welcome to our hospital.", "mn": "Сайхан байна! Манай эмнэлэгт тавтай морил."}, {"speaker": "Dr. Sara", "en": "Thank you very much.", "mn": "Маш их баярлалаа."}, {"speaker": "Dr. Bat", "en": "See you later, Sara.", "mn": "Дараа уулзъя, Сара."}, {"speaker": "Dr. Sara", "en": "Goodbye!", "mn": "Баяртай!"}], "vocab": [{"en": "hello / hi", "mn": "сайн уу", "example": "Hello, Doctor!"}, {"en": "good morning", "mn": "өглөөний мэнд", "example": "Good morning, everyone."}, {"en": "my name is …", "mn": "намайг … гэдэг", "example": "My name is Oyunaa."}, {"en": "nice to meet you", "mn": "танилцахад таатай байна", "example": "Nice to meet you, Dr. Lee."}, {"en": "doctor", "mn": "эмч", "example": "I am a doctor."}, {"en": "hospital", "mn": "эмнэлэг", "example": "Our hospital is big."}, {"en": "welcome", "mn": "тавтай морил", "example": "Welcome to Ulaanbaatar."}, {"en": "thank you", "mn": "баярлалаа", "example": "Thank you very much."}, {"en": "goodbye", "mn": "баяртай", "example": "Goodbye! See you tomorrow."}, {"en": "see you later", "mn": "дараа уулзъя", "example": "See you later!"}], "grammar": {"title": "Verb ''to be'': I am / You are", "body": "Use ''am'' with I, and ''are'' with you. Questions change the word order.", "examples": ["I am a doctor. → Би эмч.", "You are a nurse. → Та сувилагч.", "Are you a doctor? — Yes, I am. → Та эмч үү? — Тийм."]}, "speaking": ["Introduce yourself out loud: name + job + workplace. Repeat 3 times.", "Greet a colleague in English today and say ''Nice to meet you''.", "Record yourself saying the dialogue lines of Dr. Sara.", "Practice: ''I am an insurance doctor at … hospital.''", "Say goodbye three different ways: Goodbye / See you later / Bye."], "quiz": [{"q": "Which is a morning greeting?", "options": ["Good night", "Good morning", "Goodbye", "See you"], "answer": 1}, {"q": "''Namaig Bat gedeg'' in English is…", "options": ["I am fine", "My name is Bat", "You are Bat", "He is Bat"], "answer": 1}, {"q": "I ___ a doctor.", "options": ["are", "is", "am", "be"], "answer": 2}, {"q": "___ you a doctor? — Yes, I am.", "options": ["Am", "Is", "Do", "Are"], "answer": 3}, {"q": "''Танилцахад таатай байна'' means…", "options": ["See you later", "Nice to meet you", "Thank you", "Welcome"], "answer": 1}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (2, 1, 'About Me: Personal Information', 'Миний тухай: Хувийн мэдээлэл', 'https://www.youtube.com/watch?v=gIlVv9un5wA', '{"objectives": ["Say where you are from and where you live", "Talk about your job and workplace", "Ask simple questions about another person", "Spell your name in English"], "dialogue": [{"speaker": "Anna", "en": "Where are you from, Oyunaa?", "mn": "Оюунаа, та хаанаас ирсэн бэ?"}, {"speaker": "Oyunaa", "en": "I am from Mongolia. I live in Ulaanbaatar.", "mn": "Би Монголоос ирсэн. Улаанбаатарт амьдардаг."}, {"speaker": "Anna", "en": "What do you do?", "mn": "Та ямар ажил хийдэг вэ?"}, {"speaker": "Oyunaa", "en": "I am an insurance doctor. I work at a general hospital.", "mn": "Би даатгалын эмч. Нэгдсэн эмнэлэгт ажилладаг."}, {"speaker": "Anna", "en": "How do you spell your name?", "mn": "Таны нэрийг хэрхэн үсэглэх вэ?"}, {"speaker": "Oyunaa", "en": "O-Y-U-N-A-A.", "mn": "О-Ю-У-Н-А-А."}, {"speaker": "Anna", "en": "That is a beautiful name.", "mn": "Сайхан нэр байна."}, {"speaker": "Oyunaa", "en": "Thank you!", "mn": "Баярлалаа!"}], "vocab": [{"en": "country", "mn": "улс", "example": "Mongolia is my country."}, {"en": "city", "mn": "хот", "example": "Ulaanbaatar is a big city."}, {"en": "I am from …", "mn": "би …-аас ирсэн", "example": "I am from Mongolia."}, {"en": "I live in …", "mn": "би …-д амьдардаг", "example": "I live in Darkhan."}, {"en": "job / work", "mn": "ажил", "example": "I like my job."}, {"en": "I work at …", "mn": "би …-д ажилладаг", "example": "I work at a hospital."}, {"en": "nurse", "mn": "сувилагч", "example": "The nurse is kind."}, {"en": "colleague", "mn": "хамтран ажиллагч", "example": "My colleagues are friendly."}, {"en": "spell", "mn": "үсэглэх", "example": "How do you spell it?"}, {"en": "age", "mn": "нас", "example": "What is your age?"}], "grammar": {"title": "Questions with ''Where'' and ''What''", "body": "''Where'' asks about place. ''What'' asks about things or jobs. The verb comes after the question word.", "examples": ["Where are you from? → Та хаанаас ирсэн бэ?", "What do you do? → Та юу хийдэг вэ?", "Where do you work? → Та хаана ажилладаг вэ?"]}, "speaking": ["Answer aloud: Where are you from? Where do you live? What do you do?", "Spell your own name letter by letter in English.", "Describe a colleague: ''She is a nurse. She works at …''.", "Ask a family member two questions in English.", "Say your full introduction: name, city, job, workplace — 30 seconds."], "quiz": [{"q": "___ are you from?", "options": ["What", "Where", "Who", "How"], "answer": 1}, {"q": "I ___ in Ulaanbaatar.", "options": ["live", "lives", "living", "am live"], "answer": 0}, {"q": "''Би эмнэлэгт ажилладаг'' is…", "options": ["I work at a hospital", "I live in a hospital", "I am a hospital", "I go to hospital"], "answer": 0}, {"q": "What do you ___? — I am a doctor.", "options": ["work", "job", "do", "make"], "answer": 2}, {"q": "How do you ___ your name?", "options": ["say", "spell", "speak", "tell"], "answer": 1}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (3, 1, 'Numbers, Time & Dates', 'Тоо, цаг, огноо', 'https://www.youtube.com/watch?v=91sCUUVTDV8', '{"objectives": ["Count and use numbers 1–100", "Tell the time", "Say days of the week and dates", "Make a simple appointment time"], "dialogue": [{"speaker": "Reception", "en": "Good afternoon. When is your appointment?", "mn": "Өдрийн мэнд. Таны цаг хэдэн цагт вэ?"}, {"speaker": "Patient", "en": "At three o''clock on Monday.", "mn": "Даваа гарагийн 3 цагт."}, {"speaker": "Reception", "en": "Today is Friday. Your appointment is in three days.", "mn": "Өнөөдөр баасан. Таны цаг гурав хоногийн дараа."}, {"speaker": "Patient", "en": "What time is it now?", "mn": "Одоо хэдэн цаг болж байна?"}, {"speaker": "Reception", "en": "It is half past two.", "mn": "Хоёр цаг хагас."}, {"speaker": "Patient", "en": "Thank you. See you on Monday.", "mn": "Баярлалаа. Даваа гарагт уулзъя."}, {"speaker": "Reception", "en": "See you. Have a nice day!", "mn": "Уулзъя. Сайхан өдөр өнгөрүүлээрэй!"}], "vocab": [{"en": "one, two, three…", "mn": "нэг, хоёр, гурав…", "example": "I have two children."}, {"en": "o''clock", "mn": "цаг (бүтэн)", "example": "It is nine o''clock."}, {"en": "half past …", "mn": "… цаг хагас", "example": "It is half past two."}, {"en": "Monday–Sunday", "mn": "Даваа–Ням", "example": "Monday is the first day."}, {"en": "today", "mn": "өнөөдөр", "example": "Today is Tuesday."}, {"en": "tomorrow", "mn": "маргааш", "example": "See you tomorrow."}, {"en": "appointment", "mn": "цаг (уулзалтын)", "example": "I have an appointment at 10."}, {"en": "week", "mn": "долоо хоног", "example": "One week has seven days."}, {"en": "month", "mn": "сар", "example": "January is the first month."}, {"en": "What time is it?", "mn": "Хэдэн цаг болж байна?", "example": "What time is it now?"}], "grammar": {"title": "Prepositions of time: at / on / in", "body": "Use AT with clock times, ON with days, IN with months and years.", "examples": ["at 3 o''clock → 3 цагт", "on Monday → даваа гарагт", "in January → 1-р сард"]}, "speaking": ["Count aloud from 1 to 20, then by tens to 100.", "Say today''s day and date in English.", "Tell the current time out loud every hour today.", "Practice: ''My appointment is at … on …''.", "Say your birthday: ''My birthday is in (month)''."], "quiz": [{"q": "It is 2:30. → It is ___.", "options": ["two thirty o''clock", "half past two", "two and half", "thirty past two"], "answer": 1}, {"q": "Your appointment is ___ Monday.", "options": ["in", "at", "on", "to"], "answer": 2}, {"q": "The meeting is ___ 9 o''clock.", "options": ["on", "in", "at", "by"], "answer": 2}, {"q": "''Маргааш'' means…", "options": ["today", "yesterday", "tomorrow", "week"], "answer": 2}, {"q": "How many days are in a week?", "options": ["five", "six", "seven", "ten"], "answer": 2}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (4, 1, 'My Family & People', 'Гэр бүл ба хүмүүс', 'https://www.youtube.com/watch?v=8tZsPvh2dJI', '{"objectives": ["Name family members", "Describe people simply", "Use ''have / has''", "Talk about ages"], "dialogue": [{"speaker": "Tuya", "en": "Do you have a big family, John?", "mn": "Жон, та том гэр бүлтэй юу?"}, {"speaker": "John", "en": "Yes. I have a wife and two children.", "mn": "Тийм. Би эхнэр, хоёр хүүхэдтэй."}, {"speaker": "Tuya", "en": "How old are your children?", "mn": "Хүүхдүүд тань хэдэн настай вэ?"}, {"speaker": "John", "en": "My son is ten and my daughter is seven.", "mn": "Хүү маань арван настай, охин маань долоон настай."}, {"speaker": "Tuya", "en": "I have one brother. He is a doctor too.", "mn": "Би нэг ахтай. Тэр бас эмч."}, {"speaker": "John", "en": "Really? Doctors are in your family!", "mn": "Тийм үү? Танай гэр бүл эмч нэртэй юм!"}, {"speaker": "Tuya", "en": "Yes, my mother is a nurse.", "mn": "Тийм ээ, ээж маань сувилагч."}], "vocab": [{"en": "family", "mn": "гэр бүл", "example": "My family is small."}, {"en": "mother / father", "mn": "ээж / аав", "example": "My mother is a nurse."}, {"en": "wife / husband", "mn": "эхнэр / нөхөр", "example": "His wife is a teacher."}, {"en": "son / daughter", "mn": "хүү / охин", "example": "My daughter is seven."}, {"en": "brother / sister", "mn": "ах, дүү (эр) / эгч, дүү (эм)", "example": "I have one brother."}, {"en": "children", "mn": "хүүхдүүд", "example": "They have three children."}, {"en": "How old …?", "mn": "хэдэн настай …?", "example": "How old is your son?"}, {"en": "years old", "mn": "настай", "example": "I am forty years old."}, {"en": "tall / short", "mn": "өндөр / намхан", "example": "My father is tall."}, {"en": "kind", "mn": "эелдэг", "example": "The nurse is kind."}], "grammar": {"title": "have / has", "body": "Use HAVE with I, you, we, they. Use HAS with he, she, it.", "examples": ["I have two children. → Би хоёр хүүхэдтэй.", "She has one brother. → Тэр нэг ахтай.", "Do you have a family? → Та гэр бүлтэй юу?"]}, "speaking": ["Describe your family in 5 sentences out loud.", "Say the ages of three family members.", "Describe one colleague: tall/short, kind, job.", "Ask someone: ''Do you have children? How old are they?''", "Show a family photo and name everyone in English."], "quiz": [{"q": "She ___ two children.", "options": ["have", "has", "haves", "is"], "answer": 1}, {"q": "''Охин'' means…", "options": ["son", "wife", "daughter", "sister"], "answer": 2}, {"q": "How ___ is your son? — He is ten.", "options": ["old", "age", "year", "many"], "answer": 0}, {"q": "I ___ one brother.", "options": ["has", "am", "have", "is"], "answer": 2}, {"q": "My father is a doctor, and my mother is a ___.", "options": ["hospital", "nurse", "family", "children"], "answer": 1}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (5, 1, 'A Doctor''s Day: Daily Routines', 'Эмчийн өдөр: Өдөр тутмын үйл', 'https://www.youtube.com/watch?v=5iWUZg6Te1k', '{"objectives": ["Describe your daily routine", "Use present simple verbs", "Say how often you do things", "Talk about your work schedule"], "dialogue": [{"speaker": "Amar", "en": "What time do you get up, Dr. Kim?", "mn": "Доктор Ким, та хэдэн цагт босдог вэ?"}, {"speaker": "Dr. Kim", "en": "I get up at six. I start work at eight.", "mn": "Би зургаан цагт босдог. Наймд ажлаа эхэлдэг."}, {"speaker": "Amar", "en": "Do you see many patients?", "mn": "Та олон өвчтөн үздэг үү?"}, {"speaker": "Dr. Kim", "en": "Yes, I see about twenty patients every day.", "mn": "Тийм, өдөрт ойролцоогоор хорин өвчтөн үздэг."}, {"speaker": "Amar", "en": "When do you finish work?", "mn": "Та хэдэн цагт ажлаа дуусгадаг вэ?"}, {"speaker": "Dr. Kim", "en": "At five. Then I have dinner with my family.", "mn": "Тавд. Дараа нь гэр бүлтэйгээ оройн хоол иддэг."}, {"speaker": "Amar", "en": "You work hard!", "mn": "Та шаргуу ажилладаг юм!"}], "vocab": [{"en": "get up", "mn": "босох", "example": "I get up at 6."}, {"en": "start work", "mn": "ажил эхлэх", "example": "I start work at 8."}, {"en": "finish work", "mn": "ажил дуусгах", "example": "I finish work at 5."}, {"en": "every day", "mn": "өдөр бүр", "example": "I check emails every day."}, {"en": "patient", "mn": "өвчтөн", "example": "The patient is waiting."}, {"en": "see a patient", "mn": "өвчтөн үзэх", "example": "I see patients in the morning."}, {"en": "have lunch", "mn": "өдрийн хоол идэх", "example": "We have lunch at noon."}, {"en": "go home", "mn": "гэртээ харих", "example": "I go home at six."}, {"en": "usually", "mn": "ихэвчлэн", "example": "I usually work on Mondays."}, {"en": "sometimes", "mn": "заримдаа", "example": "Sometimes I work late."}], "grammar": {"title": "Present Simple: I work / She works", "body": "For routines, use the base verb. Add -s for he/she/it. Questions use do/does.", "examples": ["I see patients every day. → Би өдөр бүр өвчтөн үздэг.", "She works at a clinic. → Тэр эмнэлэгт ажилладаг.", "What time do you get up? → Та хэдэн цагт босдог вэ?"]}, "speaking": ["Describe your day from morning to night — 8 sentences.", "Say your work schedule: start time, lunch, finish time.", "Use ''usually'' and ''sometimes'' in two true sentences.", "Ask a colleague: ''What time do you start work?''", "Describe a colleague''s routine using he/she + verb-s."], "quiz": [{"q": "I ___ up at six o''clock.", "options": ["gets", "get", "getting", "got"], "answer": 1}, {"q": "She ___ at a general hospital.", "options": ["work", "works", "working", "is work"], "answer": 1}, {"q": "''Өвчтөн'' means…", "options": ["nurse", "medicine", "patient", "doctor"], "answer": 2}, {"q": "What time ___ you finish work?", "options": ["are", "does", "is", "do"], "answer": 3}, {"q": "I ___ work late.", "options": ["sometimes", "sometime", "always am", "usually am"], "answer": 0}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (6, 1, 'In the Hospital: Places & Directions', 'Эмнэлэгт: Байршил ба чиглэл', 'https://www.youtube.com/watch?v=P5GzQmNnHss', '{"objectives": ["Name hospital departments and places", "Give and understand simple directions", "Use ''there is / there are''", "Help a visitor find a room"], "dialogue": [{"speaker": "Visitor", "en": "Excuse me, where is the pharmacy?", "mn": "Уучлаарай, эмийн сан хаана байдаг вэ?"}, {"speaker": "Dr. Bold", "en": "It is on the first floor, next to reception.", "mn": "Нэг давхарт, бүртгэлийн хажууд байгаа."}, {"speaker": "Visitor", "en": "And where is Room 205?", "mn": "205 тоот өрөө хаана вэ?"}, {"speaker": "Dr. Bold", "en": "Go straight, then turn left. It is on the second floor.", "mn": "Чигээрээ яваад зүүн тийш эргэ. Хоёр давхарт байгаа."}, {"speaker": "Visitor", "en": "Is there an elevator?", "mn": "Цахилгаан шат байгаа юу?"}, {"speaker": "Dr. Bold", "en": "Yes, there is. It is behind you.", "mn": "Тийм, байгаа. Таны ард байна."}, {"speaker": "Visitor", "en": "Thank you so much!", "mn": "Маш их баярлалаа!"}], "vocab": [{"en": "reception", "mn": "бүртгэл, хүлээн авах", "example": "Ask at reception."}, {"en": "pharmacy", "mn": "эмийн сан", "example": "The pharmacy is downstairs."}, {"en": "laboratory", "mn": "лаборатори", "example": "The laboratory is on the third floor."}, {"en": "emergency room", "mn": "яаралтай тусламж", "example": "Go to the emergency room!"}, {"en": "floor", "mn": "давхар", "example": "My office is on the second floor."}, {"en": "turn left / right", "mn": "зүүн / баруун тийш эргэх", "example": "Turn right at the door."}, {"en": "go straight", "mn": "чигээрээ явах", "example": "Go straight ahead."}, {"en": "next to", "mn": "хажууд", "example": "The lab is next to the pharmacy."}, {"en": "behind", "mn": "ард", "example": "The elevator is behind you."}, {"en": "elevator / stairs", "mn": "цахилгаан шат / шат", "example": "Take the stairs."}], "grammar": {"title": "There is / There are", "body": "Use ''there is'' for one thing, ''there are'' for many. Questions: Is there…? Are there…?", "examples": ["There is an elevator. → Цахилгаан шат байгаа.", "There are two laboratories. → Хоёр лаборатори байгаа.", "Is there a pharmacy? → Эмийн сан байгаа юу?"]}, "speaking": ["Name five places in your hospital in English.", "Give directions from the entrance to your office out loud.", "Practice: ''It is on the … floor, next to …''.", "Ask and answer: ''Is there a pharmacy in your hospital?''", "Draw a simple map of your workplace and describe it."], "quiz": [{"q": "___ there an elevator? — Yes, there is.", "options": ["Are", "Is", "Do", "Have"], "answer": 1}, {"q": "The pharmacy is ___ to reception.", "options": ["behind", "next", "on", "in"], "answer": 1}, {"q": "''Зүүн тийш эргэ'' means…", "options": ["go straight", "turn right", "turn left", "go up"], "answer": 2}, {"q": "There ___ two laboratories.", "options": ["is", "are", "be", "has"], "answer": 1}, {"q": "My office is ___ the second floor.", "options": ["at", "in", "on", "by"], "answer": 2}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (7, 1, 'Food & Healthy Habits', 'Хоол ба эрүүл дадал', 'https://www.youtube.com/watch?v=SlTrn13aez4', '{"objectives": ["Talk about food and drinks", "Say what you like and don''t like", "Give simple health advice", "Use ''should'' for advice"], "dialogue": [{"speaker": "Dr. Suvd", "en": "Do you eat breakfast every day?", "mn": "Та өдөр бүр өглөөний цай уудаг уу?"}, {"speaker": "Patient", "en": "No, I don''t. I only drink coffee.", "mn": "Үгүй. Би зөвхөн кофе уудаг."}, {"speaker": "Dr. Suvd", "en": "You should eat breakfast. It is important.", "mn": "Та өглөөний цай уух хэрэгтэй. Энэ чухал."}, {"speaker": "Patient", "en": "What should I eat?", "mn": "Би юу идэх хэрэгтэй вэ?"}, {"speaker": "Dr. Suvd", "en": "Eat fruit and drink water. Don''t drink too much coffee.", "mn": "Жимс идэж, ус ууж байгаарай. Хэт их кофе уухгүй байх."}, {"speaker": "Patient", "en": "OK. I like apples.", "mn": "За. Би алимд дуртай."}, {"speaker": "Dr. Suvd", "en": "Perfect. Apples are healthy.", "mn": "Маш сайн. Алим эрүүл мэндэд сайн."}], "vocab": [{"en": "breakfast / lunch / dinner", "mn": "өглөөний / өдрийн / оройн хоол", "example": "I have lunch at noon."}, {"en": "eat / drink", "mn": "идэх / уух", "example": "Drink more water."}, {"en": "water", "mn": "ус", "example": "Water is good for you."}, {"en": "fruit / vegetables", "mn": "жимс / хүнсний ногоо", "example": "Eat more vegetables."}, {"en": "meat", "mn": "мах", "example": "We eat meat in winter."}, {"en": "tea / coffee", "mn": "цай / кофе", "example": "Mongolian milk tea is famous."}, {"en": "healthy", "mn": "эрүүл", "example": "This food is healthy."}, {"en": "I like …", "mn": "би …-д дуртай", "example": "I like apples."}, {"en": "I don''t like …", "mn": "би …-д дургүй", "example": "I don''t like fast food."}, {"en": "should", "mn": "хэрэгтэй (зөвлөгөө)", "example": "You should sleep more."}], "grammar": {"title": "should / shouldn''t for advice", "body": "Doctors give advice with ''should''. Negative: shouldn''t (= should not).", "examples": ["You should drink water. → Та ус уух хэрэгтэй.", "You shouldn''t smoke. → Та тамхи татаж болохгүй.", "What should I eat? → Би юу идэх хэрэгтэй вэ?"]}, "speaking": ["Say three foods you like and two you don''t like.", "Give three pieces of advice to a patient with ''should''.", "Describe your breakfast in English.", "Practice: ''You should… / You shouldn''t…'' — 5 sentences.", "Tell a family member one healthy habit in English."], "quiz": [{"q": "You ___ drink more water.", "options": ["should", "are", "do", "have"], "answer": 0}, {"q": "''Жимс'' means…", "options": ["meat", "fruit", "water", "tea"], "answer": 1}, {"q": "I ___ like fast food.", "options": ["no", "not", "don''t", "am not"], "answer": 2}, {"q": "You ___ smoke. It is bad for you.", "options": ["should", "shouldn''t", "do", "must to"], "answer": 1}, {"q": "Which is the morning meal?", "options": ["dinner", "lunch", "breakfast", "snack"], "answer": 2}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (8, 1, 'The Body & Simple Symptoms', 'Бие ба энгийн шинж тэмдэг', 'https://www.youtube.com/watch?v=RaB5Bydz8rE', '{"objectives": ["Name parts of the body", "Ask ''What''s the matter?''", "Describe simple symptoms", "Respond with simple advice"], "dialogue": [{"speaker": "Dr. Erdene", "en": "Good morning. What''s the matter?", "mn": "Өглөөний мэнд. Юу нь болохгүй байна вэ?"}, {"speaker": "Patient", "en": "I have a headache and a sore throat.", "mn": "Толгой өвдөж, хоолой хорсож байна."}, {"speaker": "Dr. Erdene", "en": "Do you have a fever?", "mn": "Халуурч байна уу?"}, {"speaker": "Patient", "en": "Yes, a little. And my back hurts.", "mn": "Тийм, бага зэрэг. Бас нуруу өвдөж байна."}, {"speaker": "Dr. Erdene", "en": "How long have you felt this way?", "mn": "Хэдий хугацаанд ийм байна вэ?"}, {"speaker": "Patient", "en": "For two days.", "mn": "Хоёр хоног болж байна."}, {"speaker": "Dr. Erdene", "en": "OK. Rest, drink warm water, and take this medicine.", "mn": "За. Амарч, бүлээн ус ууж, энэ эмийг уугаарай."}], "vocab": [{"en": "head / headache", "mn": "толгой / толгой өвдөх", "example": "I have a headache."}, {"en": "throat / sore throat", "mn": "хоолой / хоолой хорсох", "example": "My throat is sore."}, {"en": "stomach", "mn": "гэдэс", "example": "My stomach hurts."}, {"en": "back", "mn": "нуруу", "example": "My back hurts."}, {"en": "fever", "mn": "халуун", "example": "The child has a fever."}, {"en": "cough", "mn": "ханиалга", "example": "I have a bad cough."}, {"en": "hurt", "mn": "өвдөх", "example": "Where does it hurt?"}, {"en": "medicine", "mn": "эм", "example": "Take this medicine twice a day."}, {"en": "rest", "mn": "амрах", "example": "You should rest."}, {"en": "What''s the matter?", "mn": "Юу нь болохгүй байна вэ?", "example": "What''s the matter today?"}], "grammar": {"title": "have + symptom / … hurts", "body": "Use ''I have a …'' for symptoms, and ''(body part) hurts'' for pain.", "examples": ["I have a headache. → Толгой өвдөж байна.", "My back hurts. → Нуруу өвдөж байна.", "Do you have a fever? → Халуурч байна уу?"]}, "speaking": ["Point to five body parts and name them in English.", "Practice the doctor''s questions: ''What''s the matter? Do you have a fever?''", "Describe two symptoms with ''I have a …''.", "Role-play the full dialogue — both roles, out loud.", "Give advice for a cold: three sentences with ''should''."], "quiz": [{"q": "''Толгой өвдөж байна'' is…", "options": ["I have a fever", "I have a headache", "My back hurts", "I have a cough"], "answer": 1}, {"q": "My back ___.", "options": ["hurt", "hurting", "hurts", "is hurt"], "answer": 2}, {"q": "Do you have a ___? — Yes, 38.5°C.", "options": ["cough", "fever", "headache", "medicine"], "answer": 1}, {"q": "Take this ___ twice a day.", "options": ["rest", "water", "medicine", "food"], "answer": 2}, {"q": "What''s the ___? — I feel sick.", "options": ["problem you", "matter", "wrong", "happen"], "answer": 1}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (9, 1, 'On the Phone: Appointments', 'Утсаар: Цаг захиалга', 'https://www.youtube.com/watch?v=ka-dwb-O-uE', '{"objectives": ["Answer the phone politely", "Make and change an appointment", "Take a simple message", "Confirm details by repeating"], "dialogue": [{"speaker": "Reception", "en": "Good morning, City Hospital. How can I help you?", "mn": "Өглөөний мэнд, Хотын эмнэлэг. Танд юугаар туслах вэ?"}, {"speaker": "Caller", "en": "Hello. I would like to make an appointment, please.", "mn": "Сайн байна уу. Би цаг захиалмаар байна."}, {"speaker": "Reception", "en": "Of course. What is your name?", "mn": "Тэгэлгүй яахав. Таны нэр хэн бэ?"}, {"speaker": "Caller", "en": "My name is Ganbold. G-A-N-B-O-L-D.", "mn": "Намайг Ганболд гэдэг. Г-А-Н-Б-О-Л-Д."}, {"speaker": "Reception", "en": "Thank you. Is Tuesday at ten o''clock OK?", "mn": "Баярлалаа. Мягмар гарагийн 10 цаг болох уу?"}, {"speaker": "Caller", "en": "Yes, that is fine.", "mn": "Тийм, болно."}, {"speaker": "Reception", "en": "Great. See you on Tuesday at ten. Goodbye.", "mn": "Сайхан. Мягмарын 10 цагт уулзъя. Баяртай."}], "vocab": [{"en": "How can I help you?", "mn": "Танд юугаар туслах вэ?", "example": "Hello! How can I help you?"}, {"en": "I would like to …", "mn": "би …-маар байна", "example": "I would like to make an appointment."}, {"en": "make an appointment", "mn": "цаг захиалах", "example": "Can I make an appointment?"}, {"en": "change / cancel", "mn": "өөрчлөх / цуцлах", "example": "I need to change my appointment."}, {"en": "available", "mn": "боломжтой, сул", "example": "The doctor is available at 3."}, {"en": "Is … OK?", "mn": "… болох уу?", "example": "Is Monday OK?"}, {"en": "That is fine", "mn": "болно", "example": "Ten o''clock? That is fine."}, {"en": "message", "mn": "мэдээлэл, захиа", "example": "Can I leave a message?"}, {"en": "call back", "mn": "эргэж залгах", "example": "I will call back later."}, {"en": "Just a moment", "mn": "түр хүлээнэ үү", "example": "Just a moment, please."}], "grammar": {"title": "Polite requests: I would like… / Can I…?", "body": "''I would like…'' is a polite ''I want''. ''Can I…?'' asks permission politely.", "examples": ["I would like to make an appointment. → Би цаг захиалмаар байна.", "Can I change my appointment? → Би цагаа өөрчилж болох уу?", "Can I leave a message? → Захиа үлдээж болох уу?"]}, "speaking": ["Practice answering: ''Good morning, … hospital. How can I help you?''", "Role-play booking an appointment — both roles.", "Spell your name over an imaginary phone call.", "Practice changing an appointment: ''Can I change… to…?''", "Repeat details to confirm: ''So, Tuesday at ten. Thank you.''"], "quiz": [{"q": "I ___ like to make an appointment.", "options": ["will", "would", "should", "am"], "answer": 1}, {"q": "How can I ___ you?", "options": ["make", "give", "help", "call"], "answer": 2}, {"q": "''Цаг захиалах'' means…", "options": ["cancel an appointment", "make an appointment", "call back", "leave a message"], "answer": 1}, {"q": "___ I leave a message?", "options": ["Can", "Am", "Do", "Would to"], "answer": 0}, {"q": "Is Tuesday OK? — Yes, that is ___.", "options": ["good time", "fine", "well", "right time"], "answer": 1}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (10, 1, 'My Story: Review & Speaking', 'Миний түүх: Давтлага ба ярианы дадлага', 'https://www.youtube.com/watch?v=rhpO-cCM0u0', '{"objectives": ["Review weeks 1-9", "Tell your story: who you are, your work, your day", "Answer questions fluently at A1 level", "Complete a confident self-introduction"], "dialogue": [{"speaker": "Examiner", "en": "Tell me about yourself, please.", "mn": "Өөрийнхөө тухай ярина уу."}, {"speaker": "You", "en": "My name is …. I am from Mongolia. I am an insurance doctor.", "mn": "Намайг … гэдэг. Би Монголоос ирсэн. Би даатгалын эмч."}, {"speaker": "Examiner", "en": "What is your daily routine?", "mn": "Таны өдөр тутмын үйл ажиллагаа?"}, {"speaker": "You", "en": "I get up at six, start work at eight, and see patients every day.", "mn": "Би зургаад босч, наймд ажил эхэлж, өдөр бүр өвчтөн үздэг."}, {"speaker": "Examiner", "en": "What do you like about your job?", "mn": "Ажлынхаа юунд дуртай вэ?"}, {"speaker": "You", "en": "I like helping people. My colleagues are kind.", "mn": "Би хүмүүст туслах дуртай. Хамт олон маань эелдэг."}, {"speaker": "Examiner", "en": "Wonderful. You are ready for the next 20 weeks!", "mn": "Гайхалтай. Та дараагийн 20 долоо хоногт бэлэн боллоо!"}], "vocab": [{"en": "story", "mn": "түүх", "example": "Tell me your story."}, {"en": "about myself", "mn": "өөрийн тухай", "example": "Let me tell you about myself."}, {"en": "helping people", "mn": "хүмүүст туслах", "example": "I like helping people."}, {"en": "proud", "mn": "бахархалтай", "example": "I am proud of my work."}, {"en": "learn", "mn": "сурах", "example": "I learn English every week."}, {"en": "practice", "mn": "дадлага хийх", "example": "Practice every day."}, {"en": "improve", "mn": "сайжруулах", "example": "I want to improve my English."}, {"en": "confident", "mn": "итгэлтэй", "example": "I feel more confident now."}, {"en": "progress", "mn": "ахиц", "example": "I can see my progress."}, {"en": "future", "mn": "ирээдүй", "example": "Good luck in the future!"}], "grammar": {"title": "Review: the five key patterns", "body": "You now know five power patterns. Combine them to speak about anything at A1 level.", "examples": ["I am… / I have… → Би … / Би …-тай", "I work… I get up… (present simple) → Би ажилладаг…", "There is / are… · You should… · I would like…"]}, "speaking": ["Record a 60-second self-introduction: name, city, job, family, routine.", "Answer aloud: What do you like about your job?", "Give a patient three pieces of advice — full sentences.", "Book an imaginary appointment on the phone — full dialogue.", "Say the final dialogue as ''You'' — smooth, without reading."], "quiz": [{"q": "I am … / I have … — which is correct?", "options": ["I am two children", "I have a doctor", "I am a doctor", "I have from Mongolia"], "answer": 2}, {"q": "She ___ patients every day.", "options": ["see", "sees", "seeing", "is see"], "answer": 1}, {"q": "___ there a pharmacy here? — Yes, there is.", "options": ["Are", "Do", "Is", "Have"], "answer": 2}, {"q": "You ___ rest and drink water.", "options": ["would", "should", "are", "like"], "answer": 1}, {"q": "I ___ like to make an appointment.", "options": ["would", "should", "can", "am"], "answer": 0}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (11, 1, 'Weather & Seasons', 'Цаг агаар ба улирал', 'https://www.youtube.com/watch?v=ZfdNbSe7Prw', '{"objectives": ["Talk about today''s weather", "Name the four seasons", "Make predictions with ''going to''", "Give a weather-related safety tip to a patient"], "dialogue": [{"speaker": "Dr. Lee", "en": "It''s very cold today, isn''t it?", "mn": "Өнөөдөр их хүйтэн байна, тийм үү?"}, {"speaker": "Dr. Naran", "en": "Yes, it is. It''s minus twenty degrees.", "mn": "Тийм ээ. Хасах хорин градус байна."}, {"speaker": "Dr. Lee", "en": "Is it going to snow tomorrow?", "mn": "Маргааш цас орох болов уу?"}, {"speaker": "Dr. Naran", "en": "I think so. The forecast says heavy snow.", "mn": "Тиймдээ байх. Цаг агаарын мэдээгээр их цас ордог."}, {"speaker": "Dr. Lee", "en": "We should tell patients to be careful on the ice.", "mn": "Бид өвчтөнд мөсөн дээр болгоомжтой байхыг зөвлөх хэрэгтэй."}, {"speaker": "Dr. Naran", "en": "Good idea. Winter is hard for older patients.", "mn": "Сайн санаа. Өвөл настай өвчтөнд хэцүү байдаг."}, {"speaker": "Dr. Lee", "en": "In summer, it will be much easier.", "mn": "Зун харин илүү амархан байх болно."}], "vocab": [{"en": "weather", "mn": "цаг агаар", "example": "The weather is nice today."}, {"en": "cold / hot", "mn": "хүйтэн / халуун", "example": "It is very cold in winter."}, {"en": "snow / rain", "mn": "цас / бороо", "example": "It is going to snow."}, {"en": "wind / windy", "mn": "салхи / салхитай", "example": "It is windy today."}, {"en": "degree(s)", "mn": "градус", "example": "It is minus ten degrees."}, {"en": "forecast", "mn": "цаг агаарын мэдээ", "example": "The forecast says rain."}, {"en": "season", "mn": "улирал", "example": "My favorite season is autumn."}, {"en": "winter / summer", "mn": "өвөл / зун", "example": "Winter is long in Mongolia."}, {"en": "spring / autumn", "mn": "хавар / намар", "example": "Spring is short here."}, {"en": "be careful", "mn": "болгоомжтой байх", "example": "Be careful on the ice."}], "grammar": {"title": "going to for predictions", "body": "Use am/is/are + going to + verb to predict the future, especially based on evidence like a forecast.", "examples": ["It is going to snow. → Цас орох болов уу.", "Is it going to rain? → Бороо орох болов уу?", "We are going to have a cold winter. → Бид хүйтэн өвөлтэй байх болно."]}, "speaking": ["Describe today''s weather out loud in three sentences.", "Say what season it is and one thing you like about it.", "Predict tomorrow''s weather using ''going to''.", "Give one weather safety tip to a patient.", "Describe all four seasons — one sentence each."], "quiz": [{"q": "It ___ going to snow tomorrow.", "options": ["is", "are", "am", "be"], "answer": 0}, {"q": "''Цаг агаарын мэдээ'' means…", "options": ["season", "forecast", "weather", "degree"], "answer": 1}, {"q": "In winter, it is very ___.", "options": ["hot", "cold", "windy only", "rainy always"], "answer": 1}, {"q": "Be ___ on the ice.", "options": ["careful", "care", "carefully", "caring"], "answer": 0}, {"q": "How many seasons are there?", "options": ["two", "three", "four", "five"], "answer": 2}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (12, 1, 'Hobbies & Free Time', 'Хобби ба чөлөөт цаг', 'https://www.youtube.com/watch?v=hoyhPZDp3dE', '{"objectives": ["Talk about hobbies and interests", "Use ''like/love/enjoy + -ing''", "Ask about free time", "Describe a weekend activity"], "dialogue": [{"speaker": "Bat", "en": "What do you do in your free time?", "mn": "Та чөлөөт цагаараа юу хийдэг вэ?"}, {"speaker": "Sara", "en": "I enjoy reading and playing badminton.", "mn": "Би унших, бадминтон тоглох дуртай."}, {"speaker": "Bat", "en": "Really? I love hiking on weekends.", "mn": "Тийм үү? Би амралтын өдрүүдэд ууланд явахдаа дуртай."}, {"speaker": "Sara", "en": "That sounds relaxing. Do you go with friends?", "mn": "Сонирхолтой байна. Найзуудтайгаа явдаг уу?"}, {"speaker": "Bat", "en": "Yes, usually with two colleagues from work.", "mn": "Тийм, ихэвчлэн ажлын хоёр хамт олонтойгоо."}, {"speaker": "Sara", "en": "I should try it sometime.", "mn": "Би нэг удаа туршиж үзэх ёстой."}, {"speaker": "Bat", "en": "You are welcome to join us next week.", "mn": "Дараа долоо хоногт бидэнтэй хамт явж болно."}], "vocab": [{"en": "free time", "mn": "чөлөөт цаг", "example": "What do you do in your free time?"}, {"en": "hobby", "mn": "хобби", "example": "Reading is my hobby."}, {"en": "enjoy + -ing", "mn": "дуртай (үйл)", "example": "I enjoy reading books."}, {"en": "hiking", "mn": "ууланд явах", "example": "I love hiking."}, {"en": "weekend", "mn": "амралтын өдрүүд", "example": "See you at the weekend."}, {"en": "relaxing", "mn": "тайвшрал өгдөг", "example": "Music is relaxing."}, {"en": "play sports", "mn": "спорт тоглох", "example": "I play badminton on Sundays."}, {"en": "join", "mn": "нэгдэх", "example": "Please join us."}, {"en": "sometime", "mn": "хэзээ нэгэн цагт", "example": "I''ll try it sometime."}, {"en": "colleague", "mn": "хамт олон", "example": "Two colleagues came with me."}], "grammar": {"title": "like / love / enjoy + -ing", "body": "After like, love, and enjoy, use the -ing form of the verb.", "examples": ["I enjoy reading. → Би унших дуртай.", "She loves hiking. → Тэр ууланд явах дуртай.", "Do you like cooking? → Та хоол хийхэд дуртай юу?"]}, "speaking": ["Say three hobbies you enjoy using ''I enjoy…-ing''.", "Ask a colleague what they do in their free time.", "Describe your last weekend in three sentences.", "Invite a friend to join a hobby with you.", "Say one hobby you would like to try."], "quiz": [{"q": "I enjoy ___ books.", "options": ["read", "reads", "reading", "to read"], "answer": 2}, {"q": "''Чөлөөт цаг'' means…", "options": ["work time", "free time", "sleep time", "meal time"], "answer": 1}, {"q": "She ___ hiking on weekends.", "options": ["love", "loving", "loves", "is love"], "answer": 2}, {"q": "What do you do in your free ___?", "options": ["work", "job", "time", "hour"], "answer": 2}, {"q": "''Нэгдэх'' means…", "options": ["join", "leave", "start", "stop"], "answer": 0}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (13, 1, 'Shopping & Money', 'Худалдан авалт ба мөнгө', 'https://www.youtube.com/watch?v=5otanR_Jg2M', '{"objectives": ["Ask the price of something", "Use comparatives (cheaper / more expensive)", "Pay and ask for a receipt", "Count larger numbers with money"], "dialogue": [{"speaker": "Customer", "en": "Excuse me, how much is this jacket?", "mn": "Уучлаарай, энэ куртка хэд вэ?"}, {"speaker": "Shop assistant", "en": "It''s eighty-five thousand tugriks.", "mn": "Наян таван мянган төгрөг."}, {"speaker": "Customer", "en": "That''s expensive. Do you have a cheaper one?", "mn": "Энэ үнэтэй байна. Хямд нь байна уу?"}, {"speaker": "Shop assistant", "en": "Yes, this one is cheaper — sixty thousand.", "mn": "Тийм ээ, энэ нь хямд — жаран мянга."}, {"speaker": "Customer", "en": "Great, I''ll take it. Can I pay by card?", "mn": "Гоё, авъя. Картаар төлж болох уу?"}, {"speaker": "Shop assistant", "en": "Of course. Would you like a receipt?", "mn": "Мэдээж. Баримт хэрэгтэй юу?"}, {"speaker": "Customer", "en": "Yes, please. Thank you.", "mn": "Тийм, өгнө үү. Баярлалаа."}], "vocab": [{"en": "How much is …?", "mn": "… хэд вэ?", "example": "How much is this bag?"}, {"en": "price", "mn": "үнэ", "example": "The price is high."}, {"en": "expensive / cheap", "mn": "үнэтэй / хямд", "example": "This shop is expensive."}, {"en": "cheaper / more expensive", "mn": "хямд / илүү үнэтэй", "example": "This one is cheaper."}, {"en": "pay", "mn": "төлөх", "example": "I will pay by card."}, {"en": "cash / card", "mn": "бэлэн мөнгө / карт", "example": "Do you accept cards?"}, {"en": "receipt", "mn": "баримт", "example": "Can I have a receipt?"}, {"en": "discount", "mn": "хямдрал", "example": "Is there a discount?"}, {"en": "tugrik", "mn": "төгрөг", "example": "It costs 50,000 tugriks."}, {"en": "I''ll take it", "mn": "би авъя", "example": "OK, I''ll take it."}], "grammar": {"title": "Comparatives: -er / more + adjective", "body": "Short adjectives add -er (cheap→cheaper). Longer adjectives use ''more'' (expensive→more expensive).", "examples": ["This is cheaper than that one. → Энэ нь тэрнээс хямд.", "That jacket is more expensive. → Тэр куртка илүү үнэтэй.", "Do you have a cheaper one? → Хямд нь байна уу?"]}, "speaking": ["Ask the price of three objects around you.", "Practice: ''Do you have a cheaper one?''", "Compare two items using -er or more.", "Role-play paying at a shop — both roles.", "Say five numbers with ''thousand tugriks''."], "quiz": [{"q": "How ___ is this jacket?", "options": ["much", "many", "price", "cost"], "answer": 0}, {"q": "This bag is ___ than that one. (cheap)", "options": ["cheap", "cheaper", "more cheap", "cheapest"], "answer": 1}, {"q": "''Баримт'' means…", "options": ["price", "discount", "receipt", "cash"], "answer": 2}, {"q": "Can I ___ by card?", "options": ["pay", "paying", "pays", "to pay"], "answer": 0}, {"q": "That laptop is more ___ than this one.", "options": ["expensive", "expense", "expensively", "expenses"], "answer": 0}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (14, 1, 'Clothes & Appearance', 'Хувцас ба өнгө төрх', 'https://www.youtube.com/watch?v=CkwcvqqEO3E', '{"objectives": ["Name common clothing items", "Describe what someone is wearing", "Use present continuous", "Describe a person''s appearance politely"], "dialogue": [{"speaker": "Amar", "en": "What is the doctor wearing today?", "mn": "Эмч өнөөдөр юу өмссөн байна вэ?"}, {"speaker": "Tuya", "en": "She is wearing a white coat and glasses.", "mn": "Тэр цагаан халат, нүдний шил зүүсэн байна."}, {"speaker": "Amar", "en": "And the new nurse — what does he look like?", "mn": "Шинэ сувилагч ямар харагдаж байна вэ?"}, {"speaker": "Tuya", "en": "He is tall, with short black hair.", "mn": "Тэр өндөр, богино хар үстэй."}, {"speaker": "Amar", "en": "Is he wearing a uniform?", "mn": "Тэр дүрэмт хувцас өмссөн үү?"}, {"speaker": "Tuya", "en": "Yes, a blue uniform with a name tag.", "mn": "Тийм, нэрийн ялтастай цэнхэр дүрэмт хувцас."}, {"speaker": "Amar", "en": "Thanks, now I''ll recognize him.", "mn": "Баярлалаа, одоо би түүнийг таних болно."}], "vocab": [{"en": "clothes", "mn": "хувцас", "example": "I need new clothes."}, {"en": "wear / wearing", "mn": "өмсөх / өмссөн", "example": "She is wearing a coat."}, {"en": "uniform", "mn": "дүрэмт хувцас", "example": "Nurses wear a uniform."}, {"en": "coat / jacket", "mn": "халат / куртка", "example": "Put on your coat."}, {"en": "glasses", "mn": "нүдний шил", "example": "He wears glasses."}, {"en": "tall / short (height)", "mn": "өндөр / намхан", "example": "She is tall."}, {"en": "hair", "mn": "үс", "example": "He has short hair."}, {"en": "colour: blue / white / black", "mn": "өнгө: цэнхэр / цагаан / хар", "example": "The uniform is blue."}, {"en": "name tag", "mn": "нэрийн ялтас", "example": "Wear your name tag."}, {"en": "look like", "mn": "дүр төрхтэй байх", "example": "What does she look like?"}], "grammar": {"title": "Present continuous: is/are + -ing", "body": "Use present continuous to describe what is happening or what someone is wearing right now.", "examples": ["She is wearing a white coat. → Тэр цагаан халат өмссөн байна.", "He is wearing glasses. → Тэр нүдний шил зүүсэн байна.", "What are you wearing today? → Та өнөөдөр юу өмссөн бэ?"]}, "speaking": ["Describe what you are wearing today.", "Describe a colleague''s appearance politely.", "Practice: ''He/She is wearing…'' — 3 sentences.", "Ask ''What does he/she look like?'' and answer.", "Describe your work uniform in English."], "quiz": [{"q": "She ___ wearing a white coat.", "options": ["is", "are", "am", "be"], "answer": 0}, {"q": "''Дүрэмт хувцас'' means…", "options": ["glasses", "uniform", "name tag", "hair"], "answer": 1}, {"q": "What does he look ___?", "options": ["like", "as", "for", "on"], "answer": 0}, {"q": "He has short black ___.", "options": ["coat", "hair", "glasses", "uniform"], "answer": 1}, {"q": "I am ___ my glasses today.", "options": ["wear", "wears", "wearing", "worn"], "answer": 2}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (15, 1, 'Travel & Transportation', 'Аялал ба тээвэр', 'https://www.youtube.com/watch?v=5WGDTOm3xRk', '{"objectives": ["Talk about ways to travel", "Ask for and give simple directions on public transport", "Use ''can'' for ability/permission", "Buy a bus or taxi ticket"], "dialogue": [{"speaker": "Tourist", "en": "Excuse me, can I take a bus to the hospital?", "mn": "Уучлаарай, эмнэлэг рүү автобусаар явж болох уу?"}, {"speaker": "Local", "en": "Yes, you can. Take bus number 7.", "mn": "Тийм, болно. 7 дугаар автобусаар яваарай."}, {"speaker": "Tourist", "en": "How long does it take?", "mn": "Хэр удах вэ?"}, {"speaker": "Local", "en": "About twenty minutes, if there''s no traffic.", "mn": "Түгжрэлгүй бол ойролцоогоор хорин минут."}, {"speaker": "Tourist", "en": "Is it faster by taxi?", "mn": "Такси өдөр илүү хурдан уу?"}, {"speaker": "Local", "en": "Yes, a taxi is faster but more expensive.", "mn": "Тийм, такси хурдан ч илүү үнэтэй."}, {"speaker": "Tourist", "en": "Thank you, I''ll take the bus.", "mn": "Баярлалаа, автобусаар явъя."}], "vocab": [{"en": "travel", "mn": "аялах", "example": "I like to travel."}, {"en": "bus / taxi", "mn": "автобус / такси", "example": "Take a taxi to the airport."}, {"en": "train / plane", "mn": "галт тэрэг / онгоц", "example": "The train is slow but cheap."}, {"en": "ticket", "mn": "тасалбар", "example": "Buy a ticket first."}, {"en": "How long does it take?", "mn": "хэр удах вэ?", "example": "How long does it take by bus?"}, {"en": "traffic", "mn": "түгжрэл", "example": "There is a lot of traffic."}, {"en": "fast / slow", "mn": "хурдан / удаан", "example": "The taxi is faster."}, {"en": "can (ability)", "mn": "чадах, боломжтой", "example": "You can take bus 7."}, {"en": "station / stop", "mn": "буудал / зогсоол", "example": "The bus stop is near here."}, {"en": "arrive", "mn": "хүрэлцэн ирэх", "example": "We will arrive at nine."}], "grammar": {"title": "can for ability and permission", "body": "Use ''can'' + base verb to say what is possible or allowed. Negative: cannot / can''t.", "examples": ["You can take bus 7. → Та 7 дугаар автобусаар явж болно.", "Can I take a taxi? → Би таксигаар явж болох уу?", "I can''t drive. → Би машин жолоодож чаддаггүй."]}, "speaking": ["Ask ''How long does it take to…?'' about your commute.", "Describe how you travel to work every day.", "Practice: ''You can take bus number …''.", "Compare bus and taxi using fast/slow, cheap/expensive.", "Buy a ticket in a role-play conversation."], "quiz": [{"q": "You ___ take bus number 7.", "options": ["can", "cans", "canning", "could to"], "answer": 0}, {"q": "''Түгжрэл'' means…", "options": ["ticket", "traffic", "station", "taxi"], "answer": 1}, {"q": "How ___ does it take?", "options": ["much", "long", "far", "many"], "answer": 1}, {"q": "A taxi is faster but more ___.", "options": ["cheap", "slow", "expensive", "fast"], "answer": 2}, {"q": "We will ___ at nine o''clock.", "options": ["arrive", "arriving", "arrives", "arrived"], "answer": 0}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (16, 1, 'At the Airport: Checking In', 'Нисэх онгоцны буудалд: Бүртгүүлэх', 'https://www.youtube.com/watch?v=DUqdQjkvElo', '{"objectives": ["Check in for a flight", "Understand airport announcements", "Answer security questions", "Use ''need to'' for requirements"], "dialogue": [{"speaker": "Agent", "en": "Good morning. May I see your passport, please?", "mn": "Өглөөний мэнд. Паспортоо үзүүлнэ үү?"}, {"speaker": "Passenger", "en": "Here you are. I''m flying to Seoul.", "mn": "Ийм байна. Би Сөүл рүү нисч байна."}, {"speaker": "Agent", "en": "Do you have any bags to check in?", "mn": "Бүртгүүлэх ачаа байна уу?"}, {"speaker": "Passenger", "en": "Yes, one suitcase.", "mn": "Тийм, нэг чемодан."}, {"speaker": "Agent", "en": "You need to arrive at the gate 30 minutes before boarding.", "mn": "Та онгоцонд суухаас 30 минутын өмнө хаалганд ирэх хэрэгтэй."}, {"speaker": "Passenger", "en": "Which gate is it?", "mn": "Хэдэн дугаар хаалга вэ?"}, {"speaker": "Agent", "en": "Gate 12. Here is your boarding pass. Have a nice flight!", "mn": "12 дугаар хаалга. Энэ бол таны онгоцны тасалбар. Сайхан аяллын дурсамжтай яваарай!"}], "vocab": [{"en": "passport", "mn": "паспорт", "example": "Please show your passport."}, {"en": "check in", "mn": "бүртгүүлэх", "example": "Check in two hours early."}, {"en": "suitcase / bag", "mn": "чемодан / цүнх", "example": "I have one suitcase."}, {"en": "boarding pass", "mn": "онгоцны тасалбар", "example": "Here is your boarding pass."}, {"en": "gate", "mn": "хаалга", "example": "Go to gate 12."}, {"en": "flight", "mn": "нислэг", "example": "My flight is at 10 AM."}, {"en": "need to", "mn": "хэрэгтэй", "example": "You need to arrive early."}, {"en": "security", "mn": "аюулгүй байдлын хяналт", "example": "Go through security."}, {"en": "delay / on time", "mn": "хойшлогдох / цагтаа", "example": "The flight is on time."}, {"en": "Have a nice flight", "mn": "сайхан нислэг", "example": "Have a nice flight!"}], "grammar": {"title": "need to + verb", "body": "''Need to'' expresses a requirement or necessity, similar to ''must'' but a little softer.", "examples": ["You need to arrive early. → Та эрт ирэх хэрэгтэй.", "I need to check in. → Би бүртгүүлэх хэрэгтэй.", "Do I need a visa? → Надад виз хэрэгтэй юу?"]}, "speaking": ["Role-play checking in for a flight — both roles.", "Practice: ''You need to…'' — 3 airport instructions.", "Describe your last trip to an airport.", "Ask ''Which gate is it?'' and answer with a number.", "Say five airport words out loud with meanings."], "quiz": [{"q": "You ___ to arrive 30 minutes early.", "options": ["need", "needs", "needing", "needed"], "answer": 0}, {"q": "''Онгоцны тасалбар'' means…", "options": ["passport", "boarding pass", "suitcase", "gate"], "answer": 1}, {"q": "Please show your ___.", "options": ["gate", "passport", "flight", "security"], "answer": 1}, {"q": "Go through ___ before your gate.", "options": ["security", "suitcase", "boarding", "check"], "answer": 0}, {"q": "My flight is ___ time.", "options": ["at", "on", "in", "by"], "answer": 1}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (17, 1, 'Describing Illness in Detail', 'Өвчнийг дэлгэрэнгүй тайлбарлах', 'https://www.youtube.com/watch?v=Qn9QKZrNbeo', '{"objectives": ["Describe symptoms in more detail", "Use the present perfect (How long have you had…?)", "Understand pain scales", "Ask precise follow-up questions"], "dialogue": [{"speaker": "Dr. Oyun", "en": "How long have you had this pain?", "mn": "Энэ өвдөлт хэр удаж байна?"}, {"speaker": "Patient", "en": "I''ve had it for about a week.", "mn": "Ойролцоогоор нэг долоо хоног болж байна."}, {"speaker": "Dr. Oyun", "en": "On a scale of one to ten, how bad is the pain?", "mn": "Нэгээс арваар үнэлбэл, өвдөлт хэр их вэ?"}, {"speaker": "Patient", "en": "About seven. It gets worse at night.", "mn": "Ойролцоогоор долоо. Шөнөдөө улам ихэсдэг."}, {"speaker": "Dr. Oyun", "en": "Does it hurt more when you move?", "mn": "Хөдлөхөд илүү өвддөг үү?"}, {"speaker": "Patient", "en": "Yes, especially when I bend down.", "mn": "Тийм, ялангуяа бөхийхөд."}, {"speaker": "Dr. Oyun", "en": "Thank you. That helps me understand the problem.", "mn": "Баярлалаа. Энэ надад асуудлыг ойлгоход тусалж байна."}], "vocab": [{"en": "pain", "mn": "өвдөлт", "example": "The pain is sharp."}, {"en": "How long have you had…?", "mn": "хэр удаж байна?", "example": "How long have you had this cough?"}, {"en": "scale of one to ten", "mn": "нэгээс арван оноогоор", "example": "Rate the pain from one to ten."}, {"en": "get worse / get better", "mn": "муудах / сайжрах", "example": "It gets worse at night."}, {"en": "move / bend", "mn": "хөдлөх / бөхийх", "example": "Does it hurt when you move?"}, {"en": "sharp / dull pain", "mn": "цочмог / уйтгар өвдөлт", "example": "It is a sharp pain."}, {"en": "swelling", "mn": "хаваг", "example": "There is some swelling."}, {"en": "symptom", "mn": "шинж тэмдэг", "example": "What are your symptoms?"}, {"en": "especially", "mn": "ялангуяа", "example": "It hurts especially at night."}, {"en": "understand the problem", "mn": "асуудлыг ойлгох", "example": "This helps me understand the problem."}], "grammar": {"title": "Present Perfect: How long have you had…?", "body": "Use ''have/has + past participle'' to connect the past to now, especially for duration with ''for'' or ''since''.", "examples": ["I''ve had this pain for a week. → Энэ өвдөлт нэг долоо хоног болж байна.", "How long have you had a cough? → Ханиалга хэр удаж байна?", "She has had a fever since Monday. → Тэр даваа гарагаас хойш халуурч байна."]}, "speaking": ["Ask ''How long have you had…?'' about three symptoms.", "Practice describing pain on a 1-10 scale.", "Role-play a detailed symptom check — both roles.", "Describe when a symptom gets worse or better.", "Use ''especially'' in two true sentences."], "quiz": [{"q": "How long ___ you had this pain?", "options": ["have", "has", "did", "do"], "answer": 0}, {"q": "I ___ had a cough for three days.", "options": ["have", "has", "am", "did"], "answer": 0}, {"q": "''Хаваг'' means…", "options": ["pain", "swelling", "scale", "symptom"], "answer": 1}, {"q": "It gets ___ at night.", "options": ["worse", "worst", "bad", "worsen"], "answer": 0}, {"q": "Rate the pain from one ___ ten.", "options": ["at", "to", "in", "for"], "answer": 1}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (18, 1, 'Emergency English', 'Яаралтай тусламжийн англи хэл', 'https://www.youtube.com/watch?v=bNi6AjxtVkw', '{"objectives": ["Call for emergency help", "Give clear, urgent instructions", "Use imperatives and ''must/have to''", "State an emergency location and situation quickly"], "dialogue": [{"speaker": "Caller", "en": "Help! My colleague has collapsed!", "mn": "Тусламж! Миний хамт олон унасан!"}, {"speaker": "Operator", "en": "Stay calm. What is your exact location?", "mn": "Тайван байгаарай. Таны яг байршил хаана вэ?"}, {"speaker": "Caller", "en": "We are at Central Hospital, third floor.", "mn": "Бид Төв эмнэлэгт, гурав дугаар давхарт байна."}, {"speaker": "Operator", "en": "Is he breathing?", "mn": "Тэр амьсгалж байна уу?"}, {"speaker": "Caller", "en": "Yes, but he is not responding.", "mn": "Тийм, гэхдээ хариу өгөхгүй байна."}, {"speaker": "Operator", "en": "An ambulance is coming now. Do not move him.", "mn": "Түргэн тусламж одоо явж байна. Түүнийг бүү хөдөлгө."}, {"speaker": "Caller", "en": "OK, I understand. Please hurry.", "mn": "За, ойлголоо. Яараарай."}], "vocab": [{"en": "emergency", "mn": "яаралтай тохиолдол", "example": "Call an emergency number."}, {"en": "help!", "mn": "тусламж!", "example": "Help! Call a doctor!"}, {"en": "ambulance", "mn": "түргэн тусламж", "example": "Call an ambulance now."}, {"en": "collapse / faint", "mn": "унах / ухаан алдах", "example": "He has collapsed."}, {"en": "breathing", "mn": "амьсгалах", "example": "Is she breathing?"}, {"en": "location", "mn": "байршил", "example": "What is your location?"}, {"en": "stay calm", "mn": "тайван байх", "example": "Stay calm and wait."}, {"en": "must / have to", "mn": "заавал ... хэрэгтэй", "example": "You must call an ambulance."}, {"en": "do not move", "mn": "бүү хөдөлгө", "example": "Do not move the patient."}, {"en": "hurry", "mn": "яарах", "example": "Please hurry!"}], "grammar": {"title": "Imperatives + must/have to in emergencies", "body": "In emergencies, use short imperatives (Call! Stay! Don''t move!) and must/have to for strong necessity.", "examples": ["Call an ambulance! → Түргэн тусламж дуудаарай!", "You must stay calm. → Та заавал тайван байх хэрэгтэй.", "Do not move him. → Түүнийг бүү хөдөлгө."]}, "speaking": ["Practice the emergency call dialogue — both roles.", "Give three emergency instructions using imperatives.", "Say your workplace''s exact address in English.", "Practice: ''You must…'' — 3 emergency sentences.", "Role-play reporting an emergency location clearly and fast."], "quiz": [{"q": "___ an ambulance now!", "options": ["Call", "Calling", "Calls", "To call"], "answer": 0}, {"q": "You ___ stay calm.", "options": ["must", "should to", "can to", "would"], "answer": 0}, {"q": "''Байршил'' means…", "options": ["location", "breathing", "ambulance", "emergency"], "answer": 0}, {"q": "Do ___ move the patient.", "options": ["not", "no", "never to", "don''t to"], "answer": 0}, {"q": "Is he ___?", "options": ["breath", "breathing", "breathe", "breathed"], "answer": 1}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (19, 1, 'Medical Vocabulary I: Body Systems', 'Анагаах ухааны үгс I: Биеийн систем', 'https://www.youtube.com/watch?v=kpqX78i4zDQ', '{"objectives": ["Name the main body systems", "Recognize common condition names", "Build medical vocabulary from word parts", "Use vocabulary in short professional sentences"], "dialogue": [{"speaker": "Dr. Chinzo", "en": "Which body systems do we review today?", "mn": "Өнөөдөр аль системүүдийг хянах вэ?"}, {"speaker": "Dr. Sarnai", "en": "The cardiovascular and respiratory systems.", "mn": "Зүрх судасны болон амьсгалын системүүд."}, {"speaker": "Dr. Chinzo", "en": "This patient has a condition affecting the digestive system.", "mn": "Энэ өвчтөн хоол боловсруулах системд нөлөөлсөн өвчтэй."}, {"speaker": "Dr. Sarnai", "en": "I see. Is it chronic or acute?", "mn": "Ойлголоо. Энэ архаг уу, эсвэл цочмог уу?"}, {"speaker": "Dr. Chinzo", "en": "Chronic — she has had it for two years.", "mn": "Архаг — тэр хоёр жил болж байна."}, {"speaker": "Dr. Sarnai", "en": "Let''s check her nervous system as well.", "mn": "Мэдрэлийн системийг нь бас шалгая."}, {"speaker": "Dr. Chinzo", "en": "Good idea, for a full assessment.", "mn": "Сайн санаа, бүрэн үнэлгээ хийхийн тулд."}], "vocab": [{"en": "cardiovascular system", "mn": "зүрх судасны систем", "example": "The cardiovascular system includes the heart."}, {"en": "respiratory system", "mn": "амьсгалын систем", "example": "The respiratory system includes the lungs."}, {"en": "digestive system", "mn": "хоол боловсруулах систем", "example": "The stomach is part of the digestive system."}, {"en": "nervous system", "mn": "мэдрэлийн систем", "example": "The brain is part of the nervous system."}, {"en": "condition", "mn": "өвчний хэлбэр", "example": "This is a common condition."}, {"en": "chronic / acute", "mn": "архаг / цочмог", "example": "It is a chronic condition."}, {"en": "assessment", "mn": "үнэлгээ", "example": "We need a full assessment."}, {"en": "organ", "mn": "эрхтэн", "example": "The heart is an important organ."}, {"en": "disease", "mn": "өвчин", "example": "Heart disease is common."}, {"en": "affect", "mn": "нөлөөлөх", "example": "This disease affects the lungs."}], "grammar": {"title": "Passive voice basics: is/are + past participle", "body": "Medical English often uses the passive voice to describe what happens to a patient or organ, without focusing on who does it.", "examples": ["The lungs are affected by this disease. → Уушиг энэ өвчнөөр нөлөөлдөг.", "The condition is caused by stress. → Энэ өвчин стрессээс үүсдэг.", "The patient is being examined. → Өвчтөнийг үзэж байна."]}, "speaking": ["Name the four main body systems out loud.", "Describe one condition as chronic or acute.", "Use ''affect'' in two medical sentences.", "Explain what an organ does, in simple English.", "Record yourself naming five organs and their systems."], "quiz": [{"q": "The heart is part of the ___ system.", "options": ["digestive", "cardiovascular", "nervous", "respiratory"], "answer": 1}, {"q": "''Архаг'' means…", "options": ["acute", "chronic", "mild", "sudden"], "answer": 1}, {"q": "The lungs are part of the ___ system.", "options": ["respiratory", "digestive", "nervous", "cardiovascular"], "answer": 0}, {"q": "This disease ___ the lungs.", "options": ["affect", "affects", "affecting", "is affect"], "answer": 1}, {"q": "''Эрхтэн'' means…", "options": ["disease", "organ", "condition", "system"], "answer": 1}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (20, 1, 'Medical Vocabulary II: Diagnosis & Treatment', 'Анагаах ухааны үгс II: Оношилгоо ба эмчилгээ', 'https://www.youtube.com/watch?v=GMKRBzAnwRA', '{"objectives": ["Use diagnosis-related vocabulary", "Describe treatment options", "Use medical word-building (suffixes)", "Discuss test results with a colleague"], "dialogue": [{"speaker": "Dr. Naran", "en": "What is the diagnosis for this patient?", "mn": "Энэ өвчтөний онош юу вэ?"}, {"speaker": "Dr. Erdene", "en": "The test results confirm a mild infection.", "mn": "Шинжилгээний хариу бага зэргийн халдвар байгааг баталж байна."}, {"speaker": "Dr. Naran", "en": "What treatment do you recommend?", "mn": "Та ямар эмчилгээ зөвлөж байна вэ?"}, {"speaker": "Dr. Erdene", "en": "Antibiotics for one week, and plenty of rest.", "mn": "Нэг долоо хоногийн турш антибиотик, бас амралт."}, {"speaker": "Dr. Naran", "en": "Should we schedule a follow-up appointment?", "mn": "Дараагийн үзлэгийн цаг товлох хэрэгтэй юу?"}, {"speaker": "Dr. Erdene", "en": "Yes, in ten days to check the results.", "mn": "Тийм, арван хоногийн дараа үр дүнг шалгах."}, {"speaker": "Dr. Naran", "en": "I''ll update the patient''s file now.", "mn": "Одоо би өвчтөний хавтасыг шинэчилье."}], "vocab": [{"en": "diagnosis", "mn": "онош", "example": "The diagnosis is clear."}, {"en": "test results", "mn": "шинжилгээний хариу", "example": "The test results are ready."}, {"en": "infection", "mn": "халдвар", "example": "It is a mild infection."}, {"en": "treatment", "mn": "эмчилгээ", "example": "This treatment works well."}, {"en": "recommend", "mn": "зөвлөх", "example": "I recommend rest."}, {"en": "antibiotics", "mn": "антибиотик", "example": "Take antibiotics twice a day."}, {"en": "follow-up appointment", "mn": "давтан үзлэгийн цаг", "example": "Schedule a follow-up appointment."}, {"en": "confirm", "mn": "баталгаажуулах", "example": "The test confirms the diagnosis."}, {"en": "patient''s file / record", "mn": "өвчтөний хавтас", "example": "Update the patient''s file."}, {"en": "prescribe", "mn": "жор бичих", "example": "The doctor prescribed medicine."}], "grammar": {"title": "Medical word-building: -itis, -ology, -osis", "body": "Many medical words are built from Latin/Greek parts: -itis (inflammation), -ology (study of), -osis (condition). Recognizing these helps you understand new medical words quickly.", "examples": ["bronchitis = inflammation of the bronchi", "cardiology = the study of the heart", "diagnosis = a finding out (dia- + gnosis, knowledge)"]}, "speaking": ["Explain a diagnosis to a colleague in simple terms.", "Recommend a treatment using ''I recommend…''.", "Practice saying five medical words with -itis / -ology.", "Role-play discussing test results with a colleague.", "Say a follow-up appointment instruction out loud."], "quiz": [{"q": "The test results ___ a mild infection.", "options": ["confirm", "confirms", "confirming", "is confirm"], "answer": 0}, {"q": "''Онош'' means…", "options": ["treatment", "diagnosis", "infection", "record"], "answer": 1}, {"q": "I ___ rest and antibiotics.", "options": ["recommend", "recommends", "recommending", "am recommend"], "answer": 0}, {"q": "''-itis'' usually means…", "options": ["study of", "inflammation", "condition of", "removal of"], "answer": 1}, {"q": "Please schedule a ___ appointment.", "options": ["follow-up", "follow", "following-up", "followed"], "answer": 0}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (21, 1, 'Talking to Patients: Explaining a Diagnosis', 'Өвчтөнтэй ярих: Онош тайлбарлах', 'https://www.youtube.com/watch?v=ySmi7fyRtH4', '{"objectives": ["Explain a diagnosis in simple, non-technical language", "Check the patient understands", "Use reported speech basics", "Show empathy while giving information"], "dialogue": [{"speaker": "Dr. Bold", "en": "Mrs. Tsend, your test results are back.", "mn": "Хатагтай Цэнд, таны шинжилгээний хариу гарлаа."}, {"speaker": "Patient", "en": "What did they show, doctor?", "mn": "Тэд юу харуулж байна вэ, эмч ээ?"}, {"speaker": "Dr. Bold", "en": "You have mild high blood pressure. It''s very common.", "mn": "Танд бага зэргийн цусны даралт ихсэлт байна. Энэ нэлээд түгээмэл."}, {"speaker": "Patient", "en": "Is it serious?", "mn": "Энэ ноцтой юу?"}, {"speaker": "Dr. Bold", "en": "Not if we manage it now, with diet and medicine.", "mn": "Хэрэв бид одооноос хооллолт, эмээр зохицуулбал ноцтой биш."}, {"speaker": "Patient", "en": "I understand. What should I do first?", "mn": "Ойлголоо. Юуг эхлээд хийх хэрэгтэй вэ?"}, {"speaker": "Dr. Bold", "en": "Let''s start with a low-salt diet and daily walks.", "mn": "Давс багатай хоол, өдөр бүрийн алхалтаас эхэлье."}], "vocab": [{"en": "test results are back", "mn": "шинжилгээний хариу гарлаа", "example": "Your test results are back."}, {"en": "high blood pressure", "mn": "цусны даралт ихсэлт", "example": "You have high blood pressure."}, {"en": "common", "mn": "түгээмэл", "example": "This condition is common."}, {"en": "serious", "mn": "ноцтой", "example": "It is not serious."}, {"en": "manage (a condition)", "mn": "зохицуулах", "example": "We can manage this together."}, {"en": "diet", "mn": "хоолны дэглэм", "example": "A low-salt diet helps."}, {"en": "Do you understand?", "mn": "Та ойлгож байна уу?", "example": "Do you understand the diagnosis?"}, {"en": "in other words", "mn": "өөрөөр хэлбэл", "example": "In other words, it''s manageable."}, {"en": "first / next", "mn": "эхлээд / дараа нь", "example": "First, change your diet."}, {"en": "reassure", "mn": "тайвшруулах", "example": "The doctor reassured the patient."}], "grammar": {"title": "Reported speech basics: said that…", "body": "To report what someone said, use ''said (that) + subject + verb (often shifted one tense back)''.", "examples": ["She said (that) she felt dizzy. → Тэр толгой эргэдэг гэж хэлсэн.", "He said the pain was better. → Тэр өвдөлт багассан гэж хэлсэн.", "The doctor said I needed rest. → Эмч надад амралт хэрэгтэй гэж хэлсэн."]}, "speaking": ["Explain a common diagnosis in simple words, out loud.", "Practice asking ''Do you understand?'' and checking comprehension.", "Report what a patient told you, using reported speech.", "Give one reassuring sentence to a worried patient.", "Role-play the full dialogue, both roles."], "quiz": [{"q": "Your test results ___ back.", "options": ["is", "are", "was", "be"], "answer": 1}, {"q": "''Ноцтой'' means…", "options": ["common", "serious", "manageable", "mild"], "answer": 1}, {"q": "She said she ___ dizzy.", "options": ["feel", "feels", "felt", "feeling"], "answer": 2}, {"q": "We can ___ this condition with diet.", "options": ["manage", "manages", "managing", "managed to"], "answer": 0}, {"q": "''Өөрөөр хэлбэл'' means…", "options": ["first of all", "in other words", "for example", "at last"], "answer": 1}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (22, 1, 'Talking to Patients: Instructions & Prescriptions', 'Өвчтөнд заавар, жор өгөх', 'https://www.youtube.com/watch?v=r6udcDREdv8', '{"objectives": ["Give clear medicine instructions", "Explain dosage and timing", "Use imperative + should for instructions", "Warn about side effects politely"], "dialogue": [{"speaker": "Dr. Munkh", "en": "Take one tablet twice a day, after meals.", "mn": "Хоолны дараа өдөрт хоёр удаа нэг ширхэг эм ууна уу."}, {"speaker": "Patient", "en": "For how many days?", "mn": "Хэдэн өдөр уух вэ?"}, {"speaker": "Dr. Munkh", "en": "For seven days. Don''t stop early, even if you feel better.", "mn": "Долоон өдөр. Сайжирсан ч гэсэн эрт зогсоож болохгүй."}, {"speaker": "Patient", "en": "Are there any side effects?", "mn": "Ямар нэгэн гаж нөлөө байна уу?"}, {"speaker": "Dr. Munkh", "en": "You might feel a little sleepy. Avoid driving.", "mn": "Бага зэрэг нойрмоглож магадгүй. Машин жолоодохоос зайлсхий."}, {"speaker": "Patient", "en": "OK, I understand. Should I take it with food?", "mn": "За, ойлголоо. Хоолтой хамт уух ёстой юу?"}, {"speaker": "Dr. Munkh", "en": "Yes, always take it after eating.", "mn": "Тийм, үргэлж хоолны дараа ууна."}], "vocab": [{"en": "tablet / pill", "mn": "шахмал / эм", "example": "Take one tablet."}, {"en": "twice a day", "mn": "өдөрт хоёр удаа", "example": "Take it twice a day."}, {"en": "dosage", "mn": "тун", "example": "Follow the correct dosage."}, {"en": "after meals", "mn": "хоолны дараа", "example": "Take medicine after meals."}, {"en": "side effect", "mn": "гаж нөлөө", "example": "Every medicine has side effects."}, {"en": "sleepy / drowsy", "mn": "нойрмог", "example": "This medicine may make you sleepy."}, {"en": "avoid", "mn": "зайлсхийх", "example": "Avoid driving after taking it."}, {"en": "stop / continue", "mn": "зогсоох / үргэлжлүүлэх", "example": "Don''t stop the medicine early."}, {"en": "prescription", "mn": "жор", "example": "Here is your prescription."}, {"en": "as directed", "mn": "заавар ёсоор", "example": "Take the medicine as directed."}], "grammar": {"title": "Instructions: imperative + should", "body": "Use the imperative for direct instructions (Take…), and ''should'' for gentler advice within the same instruction.", "examples": ["Take one tablet twice a day. → Өдөрт хоёр удаа нэг шахмал уу.", "You should avoid driving. → Та машин жолоодохоос зайлсхийх хэрэгтэй.", "Don''t stop the medicine early. → Эмийг эрт зогсоож болохгүй."]}, "speaking": ["Give three medicine instructions out loud.", "Explain a possible side effect politely.", "Practice: ''Take … tablet(s), … times a day, for … days.''", "Role-play a patient asking about side effects.", "Record yourself reading a full prescription instruction."], "quiz": [{"q": "Take one tablet ___ a day.", "options": ["two times", "twice", "two", "twicely"], "answer": 1}, {"q": "''Гаж нөлөө'' means…", "options": ["dosage", "prescription", "side effect", "tablet"], "answer": 2}, {"q": "You ___ avoid driving after this medicine.", "options": ["should", "are", "do", "have"], "answer": 0}, {"q": "Don''t ___ the medicine early.", "options": ["stop", "stops", "stopping", "stopped"], "answer": 0}, {"q": "Always take it ___ meals.", "options": ["after", "in", "on", "for"], "answer": 0}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (23, 1, 'Insurance English I: Basic Terms', 'Даатгалын англи хэл I: Үндсэн нэр томьёо', 'https://www.youtube.com/watch?v=yDLC79qIy9I', '{"objectives": ["Understand basic health insurance vocabulary", "Explain what a policy covers", "Use modal ''may/must'' for insurance rules", "Ask about coverage politely"], "dialogue": [{"speaker": "Client", "en": "Does my insurance cover this treatment?", "mn": "Миний даатгал энэ эмчилгээг хамардаг уу?"}, {"speaker": "Dr. Tuya", "en": "Let me check your policy. Yes, it is covered.", "mn": "Таны гэрээг шалгая. Тийм, хамрагдана."}, {"speaker": "Client", "en": "What is my deductible?", "mn": "Миний хувь хариуцлагын хэмжээ хэд вэ?"}, {"speaker": "Dr. Tuya", "en": "Your deductible is fifty thousand tugriks.", "mn": "Таны хувь хариуцлага тавин мянган төгрөг."}, {"speaker": "Client", "en": "And do I need pre-approval?", "mn": "Урьдчилсан зөвшөөрөл авах шаардлагатай юу?"}, {"speaker": "Dr. Tuya", "en": "You must get pre-approval for this procedure.", "mn": "Энэ эмчилгээнд урьдчилсан зөвшөөрөл авах ёстой."}, {"speaker": "Client", "en": "Thank you, I''ll contact my insurance company today.", "mn": "Баярлалаа, өнөөдөр даатгалын компанидаа хандъя."}], "vocab": [{"en": "insurance / policy", "mn": "даатгал / гэрээ", "example": "Do you have insurance?"}, {"en": "cover / covered", "mn": "хамрах / хамрагдсан", "example": "Is this treatment covered?"}, {"en": "deductible", "mn": "хувь хариуцлага", "example": "Your deductible is 50,000."}, {"en": "premium", "mn": "даатгалын шимтгэл", "example": "The monthly premium is due."}, {"en": "claim", "mn": "нэхэмжлэл", "example": "Please submit a claim."}, {"en": "pre-approval", "mn": "урьдчилсан зөвшөөрөл", "example": "You need pre-approval."}, {"en": "insurance company", "mn": "даатгалын компани", "example": "Contact your insurance company."}, {"en": "benefit", "mn": "тэтгэмж", "example": "This is a health benefit."}, {"en": "policyholder", "mn": "гэрээ эзэмшигч", "example": "You are the policyholder."}, {"en": "out-of-pocket", "mn": "өөрийн халаасны зардал", "example": "The out-of-pocket cost is low."}], "grammar": {"title": "must / may for insurance rules", "body": "Use ''must'' for a required rule, and ''may'' for something that is allowed or possible.", "examples": ["You must get pre-approval. → Та заавал урьдчилсан зөвшөөрөл авах ёстой.", "This may be covered by your policy. → Энэ таны гэрээгээр хамрагдаж болно.", "You may need extra documents. → Танд нэмэлт бичиг баримт хэрэгтэй байж болно."]}, "speaking": ["Explain ''deductible'' and ''premium'' in your own words.", "Ask ''Does my insurance cover this?'' and answer.", "Practice: ''You must…'' for one insurance rule.", "Explain what a policyholder is, in simple English.", "Role-play the full dialogue, both roles."], "quiz": [{"q": "You ___ get pre-approval for this procedure.", "options": ["must", "should to", "can to", "would"], "answer": 0}, {"q": "''Даатгалын шимтгэл'' means…", "options": ["deductible", "premium", "claim", "benefit"], "answer": 1}, {"q": "Is this treatment ___ by my insurance?", "options": ["cover", "covers", "covered", "covering"], "answer": 2}, {"q": "''Гэрээ эзэмшигч'' means…", "options": ["insurance company", "policyholder", "claim", "benefit"], "answer": 1}, {"q": "Please submit a ___.", "options": ["premium", "deductible", "claim", "policyholder"], "answer": 2}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (24, 1, 'Insurance English II: Claims & Coverage', 'Даатгалын англи хэл II: Нэхэмжлэл ба хамрагдал', 'https://www.youtube.com/watch?v=vuYz_aXwyCM', '{"objectives": ["File and explain an insurance claim", "Discuss what is and isn''t covered", "Use first conditional (If you have…, you will…)", "Handle a denied claim politely"], "dialogue": [{"speaker": "Client", "en": "I''d like to file a claim for my last visit.", "mn": "Би сүүлийн үзлэгийнхээ талаар нэхэмжлэл гаргамаар байна."}, {"speaker": "Dr. Naran", "en": "Sure. If you submit the receipt, we will process it this week.", "mn": "Мэдээж. Хэрэв та баримтаа өгвөл бид энэ долоо хоногт боловсруулна."}, {"speaker": "Client", "en": "What if the claim is denied?", "mn": "Хэрэв нэхэмжлэл татгалзагдвал яах вэ?"}, {"speaker": "Dr. Naran", "en": "Then you can appeal within thirty days.", "mn": "Тэгвэл та гучин хоногийн дотор давж заалдаж болно."}, {"speaker": "Client", "en": "Is physical therapy covered under my plan?", "mn": "Миний төлөвлөгөөнд бариа засал хамрагддаг уу?"}, {"speaker": "Dr. Naran", "en": "Yes, up to ten sessions per year.", "mn": "Тийм, жилд арван удаа хүртэл."}, {"speaker": "Client", "en": "That''s very helpful, thank you.", "mn": "Их тустай байлаа, баярлалаа."}], "vocab": [{"en": "file a claim", "mn": "нэхэмжлэл гаргах", "example": "I want to file a claim."}, {"en": "process (a claim)", "mn": "боловсруулах", "example": "We will process your claim."}, {"en": "deny / denied", "mn": "татгалзах / татгалзсан", "example": "The claim was denied."}, {"en": "appeal", "mn": "давж заалдах", "example": "You can appeal the decision."}, {"en": "within (30 days)", "mn": "дотор (30 хоногийн)", "example": "Appeal within 30 days."}, {"en": "plan", "mn": "төлөвлөгөө", "example": "Physical therapy is under your plan."}, {"en": "session", "mn": "удаа, суулт", "example": "Ten sessions per year."}, {"en": "submit (documents)", "mn": "хүргүүлэх, өгөх", "example": "Submit your receipt."}, {"en": "reimbursement", "mn": "нөхөн олговор", "example": "You will receive reimbursement."}, {"en": "eligible", "mn": "эрх бүхий", "example": "You are eligible for this benefit."}], "grammar": {"title": "First conditional: If + present, will + verb", "body": "Use the first conditional for real, likely future results: If + present simple, … will + base verb.", "examples": ["If you submit the receipt, we will process it. → Хэрэв баримтаа өгвөл бид боловсруулна.", "If the claim is denied, you will appeal. → Хэрэв нэхэмжлэл татгалзвал давж заалдана.", "If you are eligible, you will get reimbursement. → Хэрэв эрх байвал нөхөн олговор авна."]}, "speaking": ["Practice filing a claim out loud, step by step.", "Use the first conditional in three sentences.", "Explain what to do if a claim is denied.", "Ask ''Is … covered under my plan?'' about a treatment.", "Role-play the full dialogue, both roles."], "quiz": [{"q": "If you submit the receipt, we ___ process it.", "options": ["will", "would", "are", "do"], "answer": 0}, {"q": "''Татгалзсан'' means…", "options": ["approved", "denied", "submitted", "eligible"], "answer": 1}, {"q": "You can ___ the decision within 30 days.", "options": ["appeal", "appeals", "appealing", "appealed"], "answer": 0}, {"q": "''Нөхөн олговор'' means…", "options": ["premium", "reimbursement", "deductible", "claim"], "answer": 1}, {"q": "Physical therapy is covered — ten ___ per year.", "options": ["sessions", "premiums", "claims", "plans"], "answer": 0}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (25, 1, 'Insurance English III: Explaining a Policy', 'Даатгалын англи хэл III: Гэрээг тайлбарлах', 'https://www.youtube.com/watch?v=-58VD3z7ZiQ', '{"objectives": ["Explain an insurance policy clearly to a patient", "Summarize coverage in simple terms", "Compare basic and professional membership plans", "Answer common patient questions about cost"], "dialogue": [{"speaker": "Patient", "en": "Can you explain what my plan covers, simply?", "mn": "Миний төлөвлөгөө юуг хамардгийг энгийнээр тайлбарлаж болох уу?"}, {"speaker": "Dr. Sarnai", "en": "Of course. It covers check-ups, basic tests, and medicine.", "mn": "Мэдээж. Энэ нь үзлэг, энгийн шинжилгээ, эм хамардаг."}, {"speaker": "Patient", "en": "Does it cover surgery?", "mn": "Мэс засал хамрагддаг уу?"}, {"speaker": "Dr. Sarnai", "en": "Major surgery is covered up to eighty percent.", "mn": "Том мэс заслыг наян хувь хүртэл хамардаг."}, {"speaker": "Patient", "en": "What do I pay myself?", "mn": "Би өөрөө хэдийг төлдөг вэ?"}, {"speaker": "Dr. Sarnai", "en": "You pay the remaining twenty percent, plus your deductible.", "mn": "Та үлдсэн хорин хувь болон хувь хариуцлагаа төлдөг."}, {"speaker": "Patient", "en": "Now I understand it much better. Thank you.", "mn": "Одоо би илүү сайн ойлголоо. Баярлалаа."}], "vocab": [{"en": "explain simply", "mn": "энгийнээр тайлбарлах", "example": "Let me explain simply."}, {"en": "check-up", "mn": "үзлэг", "example": "An annual check-up is covered."}, {"en": "surgery", "mn": "мэс засал", "example": "Surgery is partly covered."}, {"en": "percent (%)", "mn": "хувь", "example": "Eighty percent is covered."}, {"en": "remaining", "mn": "үлдсэн", "example": "You pay the remaining amount."}, {"en": "plan / membership", "mn": "төлөвлөгөө / гишүүнчлэл", "example": "Upgrade your membership plan."}, {"en": "compare", "mn": "харьцуулах", "example": "Let''s compare the two plans."}, {"en": "cost", "mn": "зардал", "example": "What is the total cost?"}, {"en": "summary", "mn": "хураангуй", "example": "Here is a summary of your plan."}, {"en": "understand better", "mn": "илүү сайн ойлгох", "example": "Now I understand better."}], "grammar": {"title": "Summarizing clearly: in short / to summarize", "body": "Use short signal phrases to help patients follow a summary of complex information.", "examples": ["In short, most costs are covered. → Товчоор хэлбэл, ихэнх зардал хамрагддаг.", "To summarize, you pay 20 percent. → Дүгнэвэл, та хорин хувийг төлнө.", "In other words, it''s mostly covered. → Өөрөөр хэлбэл, ихэнхдээ хамрагддаг."]}, "speaking": ["Explain your own membership plan in simple English.", "Practice: ''In short, …'' to summarize information.", "Compare two coverage levels using percentages.", "Answer a patient''s question about surgery coverage.", "Role-play the full dialogue, both roles."], "quiz": [{"q": "Major surgery is covered ___ 80 percent.", "options": ["up to", "down to", "on to", "for to"], "answer": 0}, {"q": "''Хураангуй'' means…", "options": ["summary", "surgery", "check-up", "percent"], "answer": 0}, {"q": "You pay the ___ twenty percent.", "options": ["remain", "remaining", "remained", "remains"], "answer": 1}, {"q": "To ___, you pay 20 percent plus your deductible.", "options": ["summary", "summarize", "summarized", "summarizing"], "answer": 1}, {"q": "An annual ___ is covered by the plan.", "options": ["check-up", "surgery", "claim", "premium"], "answer": 0}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (26, 1, 'Writing Medical Notes & Referrals', 'Эмнэлгийн тэмдэглэл, шилжүүлэг бичих', 'https://www.youtube.com/watch?v=U1QdpBkAVhQ', '{"objectives": ["Write a short, clear medical note", "Use standard referral-letter phrases", "Use formal written English for records", "Structure information logically in writing"], "dialogue": [{"speaker": "Dr. Bat", "en": "Can you help me write this referral letter?", "mn": "Энэ шилжүүлгийн захидлыг бичихэд туслах уу?"}, {"speaker": "Dr. Uugii", "en": "Sure. Start with the patient''s main complaint.", "mn": "Мэдээж. Өвчтөний гол зовиуроос эхэл."}, {"speaker": "Dr. Bat", "en": "''The patient presents with chronic back pain.''", "mn": "''Өвчтөн архаг нурууны өвдөлттэй ирсэн.''"}, {"speaker": "Dr. Uugii", "en": "Good. Then add relevant history and test results.", "mn": "Сайн байна. Дараа нь холбогдох түүх, шинжилгээний хариуг нэм."}, {"speaker": "Dr. Bat", "en": "And finish with the reason for referral?", "mn": "Шилжүүлгийн шалтгаанаар дуусгах уу?"}, {"speaker": "Dr. Uugii", "en": "Exactly — ''I would be grateful for your assessment.''", "mn": "Яг тийм — ''Таны үнэлгээнд талархах болно.''"}, {"speaker": "Dr. Bat", "en": "That''s very clear. Thank you for your help.", "mn": "Маш ойлгомжтой байна. Тусламжинд баярлалаа."}], "vocab": [{"en": "referral letter", "mn": "шилжүүлгийн захидал", "example": "Write a referral letter."}, {"en": "main complaint", "mn": "гол зовиур", "example": "State the patient''s main complaint."}, {"en": "presents with", "mn": "...-ээр ирсэн", "example": "The patient presents with fever."}, {"en": "relevant history", "mn": "холбогдох түүх", "example": "Add the relevant history."}, {"en": "I would be grateful for…", "mn": "...-д талархах болно", "example": "I would be grateful for your opinion."}, {"en": "please find attached", "mn": "хавсаргасныг үзнэ үү", "example": "Please find attached the test results."}, {"en": "regarding", "mn": "холбогдуулан", "example": "Regarding your patient, Mrs. Tsend…"}, {"en": "kindly", "mn": "эелдэгээр хүсье", "example": "Kindly review the attached file."}, {"en": "further assessment", "mn": "нэмэлт үнэлгээ", "example": "I recommend further assessment."}, {"en": "Yours sincerely", "mn": "хүндэтгэсэн", "example": "Yours sincerely, Dr. Bat."}], "grammar": {"title": "Formal written phrases for medical notes", "body": "Medical writing uses set formal phrases to stay clear, professional, and consistent.", "examples": ["The patient presents with… → Өвчтөн ... ирсэн.", "I would be grateful for your assessment. → Таны үнэлгээнд талархах болно.", "Please find attached the test results. → Хавсаргасан шинжилгээний хариуг үзнэ үү."]}, "speaking": ["Write one sentence starting with ''The patient presents with…''.", "Practice saying a referral letter''s closing line aloud.", "Write a two-sentence note about a common condition.", "Use ''regarding'' and ''kindly'' in two sentences.", "Read your note aloud as if presenting it to a colleague."], "quiz": [{"q": "The patient ___ with chronic back pain.", "options": ["present", "presents", "presenting", "is present"], "answer": 1}, {"q": "''Шилжүүлгийн захидал'' means…", "options": ["prescription", "referral letter", "test result", "insurance claim"], "answer": 1}, {"q": "I would be ___ for your assessment.", "options": ["grateful", "grateing", "gratefully", "grateness"], "answer": 0}, {"q": "Please find ___ the test results.", "options": ["attach", "attached", "attaching", "attaches"], "answer": 1}, {"q": "A formal letter closing is ''Yours ___''.", "options": ["truly", "sincerely", "kindly", "regard"], "answer": 1}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (27, 1, 'Professional Phone & Email English', 'Мэргэжлийн утас ба и-мэйлийн англи хэл', 'https://www.youtube.com/watch?v=zNpmtVZFXS0', '{"objectives": ["Write a short, professional email", "Use polite phone phrases for professional calls", "Open and close formal messages correctly", "Ask for and give information formally"], "dialogue": [{"speaker": "Dr. Tamir", "en": "Hello, this is Dr. Tamir calling from MHIDA.", "mn": "Сайн байна уу, би МДЭНХ-оос Доктор Тамир байна."}, {"speaker": "Assistant", "en": "Good afternoon, Doctor. How can I help you today?", "mn": "Өдрийн мэнд, эмч ээ. Танд юугаар туслах вэ?"}, {"speaker": "Dr. Tamir", "en": "I''m calling regarding a member''s insurance file.", "mn": "Би нэгэн гишүүний даатгалын хавтасны талаар залгаж байна."}, {"speaker": "Assistant", "en": "I see. Could you send the details by email?", "mn": "Ойлголоо. Дэлгэрэнгүйг и-мэйлээр илгээж болох уу?"}, {"speaker": "Dr. Tamir", "en": "Yes, I''ll send it right after this call.", "mn": "Тийм, энэ дуудлагын дараа шууд илгээе."}, {"speaker": "Assistant", "en": "Thank you. I''ll reply within one business day.", "mn": "Баярлалаа. Би нэг ажлын өдрийн дотор хариулна."}, {"speaker": "Dr. Tamir", "en": "Perfect. Thank you for your time.", "mn": "Гайхалтай. Цаг гаргасанд баярлалаа."}], "vocab": [{"en": "This is … calling", "mn": "энэ бол ... байна", "example": "This is Dr. Tamir calling."}, {"en": "regarding", "mn": "холбогдуулан", "example": "I''m calling regarding your file."}, {"en": "Could you …?", "mn": "та ... болох уу?", "example": "Could you send the file by email?"}, {"en": "attach / attachment", "mn": "хавсаргах / хавсралт", "example": "Please see the attachment."}, {"en": "Dear Dr. …", "mn": "хүндэт доктор ...", "example": "Dear Dr. Bold,"}, {"en": "I am writing to …", "mn": "би ... бичиж байна", "example": "I am writing to ask about…"}, {"en": "business day", "mn": "ажлын өдөр", "example": "I''ll reply within one business day."}, {"en": "Thank you for your time", "mn": "цаг гаргасанд баярлалаа", "example": "Thank you for your time."}, {"en": "Best regards", "mn": "хүндэтгэсэн", "example": "Best regards, Dr. Tamir."}, {"en": "follow up", "mn": "дараа нь мэдээлэл авах", "example": "I will follow up next week."}], "grammar": {"title": "Formal openings and closings", "body": "Professional emails and calls follow set patterns: a polite opening, a clear reason for contact, and a formal closing.", "examples": ["Dear Dr. Bold, I am writing to… → Хүндэт доктор Болд, би ...-н талаар бичиж байна.", "Could you please send…? → Та ...-г илгээж болох уу?", "Best regards, Dr. Tamir → Хүндэтгэсэн, Доктор Тамир"]}, "speaking": ["Practice starting a phone call: ''This is Dr. … calling.''", "Write a 3-line formal email requesting information.", "Practice ''Could you …?'' requests, politely, out loud.", "Say a formal email closing aloud: ''Best regards, …''.", "Role-play the full phone dialogue, both roles."], "quiz": [{"q": "This is Dr. Tamir ___ from MHIDA.", "options": ["call", "calling", "calls", "called"], "answer": 1}, {"q": "I''m calling ___ a member''s file.", "options": ["regard", "regarding", "regards", "regarded"], "answer": 1}, {"q": "''Хавсралт'' means…", "options": ["attachment", "appointment", "assessment", "agreement"], "answer": 0}, {"q": "I''ll reply within one business ___.", "options": ["day", "hour", "time", "moment"], "answer": 0}, {"q": "A formal closing is ''Best ___''.", "options": ["wishes only", "regards", "thanks a lot", "bye now"], "answer": 1}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (28, 1, 'Meetings & Presentations', 'Хурал ба илтгэл', 'https://www.youtube.com/watch?v=NEKZFA7L7Lg', '{"objectives": ["Use phrases for attending and running a simple meeting", "Give a short professional update", "Use ''could/shall we'' to make suggestions", "Ask for and give opinions politely"], "dialogue": [{"speaker": "Dr. Bold", "en": "Shall we begin the meeting?", "mn": "Хурлаа эхэлье үү?"}, {"speaker": "Dr. Naran", "en": "Yes. First, let''s review last month''s membership numbers.", "mn": "Тийм. Эхлээд өнгөрсөн сарын гишүүдийн тоог хянацгаая."}, {"speaker": "Dr. Bold", "en": "We now have 260 active members.", "mn": "Одоо бидэнд 260 идэвхтэй гишүүн бий."}, {"speaker": "Dr. Naran", "en": "Great progress. Could we discuss the English course next?", "mn": "Гайхалтай ахиц. Англи хэлний курсийн талаар цааш ярилцаж болох уу?"}, {"speaker": "Dr. Bold", "en": "Of course. What is your opinion on the new schedule?", "mn": "Мэдээж. Шинэ хуваарийн талаар таны бодол юу вэ?"}, {"speaker": "Dr. Naran", "en": "I think it works well for most members.", "mn": "Ихэнх гишүүдэд тохирсон гэж бодож байна."}, {"speaker": "Dr. Bold", "en": "Agreed. Let''s move to the next item.", "mn": "Санал нэгдлээ. Дараагийн асуудал руу шилжье."}], "vocab": [{"en": "Shall we…?", "mn": "...-х уу?", "example": "Shall we begin?"}, {"en": "Let''s review…", "mn": "...-г хянацгаая", "example": "Let''s review the numbers."}, {"en": "progress", "mn": "ахиц", "example": "Great progress this month."}, {"en": "Could we discuss…?", "mn": "...-н талаар ярилцаж болох уу?", "example": "Could we discuss the budget?"}, {"en": "What is your opinion on…?", "mn": "...-н талаар таны бодол юу вэ?", "example": "What is your opinion on this?"}, {"en": "I think…", "mn": "би бодохдоо…", "example": "I think it works well."}, {"en": "agreed / agree", "mn": "санал нэгдэх", "example": "I agree with you."}, {"en": "next item / next steps", "mn": "дараагийн асуудал/алхам", "example": "Let''s move to the next item."}, {"en": "update", "mn": "мэдээлэл", "example": "Give a short update."}, {"en": "in summary", "mn": "дүгнэж хэлэхэд", "example": "In summary, we made good progress."}], "grammar": {"title": "Polite suggestions: shall we / could we / let''s", "body": "Use ''Shall we…?'', ''Could we…?'', and ''Let''s…'' to make polite suggestions in a professional meeting.", "examples": ["Shall we begin? → Эхэлье үү?", "Could we discuss this next? → Үүнийг дараа ярилцаж болох уу?", "Let''s review the numbers. → Тоонуудыг хянацгаая."]}, "speaking": ["Open a meeting using ''Shall we begin?''", "Give a one-minute update about your work.", "Practice ''What is your opinion on…?'' with a colleague.", "Suggest a next step using ''Let''s…''.", "Summarize a short discussion using ''In summary…''."], "quiz": [{"q": "___ we begin the meeting?", "options": ["Shall", "Should to", "Would", "Must"], "answer": 0}, {"q": "Could we ___ the new schedule?", "options": ["discuss", "discussing", "discussed", "discusses"], "answer": 0}, {"q": "''Ахиц'' means…", "options": ["progress", "opinion", "summary", "update"], "answer": 0}, {"q": "I ___ with your idea.", "options": ["agree", "agrees", "agreeing", "am agree"], "answer": 0}, {"q": "''Дүгнэж хэлэхэд'' means…", "options": ["for example", "in summary", "on the other hand", "as a result"], "answer": 1}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (29, 1, 'Cross-Cultural Communication', 'Соёл хоорондын харилцаа', 'https://www.youtube.com/watch?v=oTPZWpQ9pbA', '{"objectives": ["Communicate respectfully with patients from other cultures", "Recognize simple cultural communication differences", "Use polite clarifying questions", "Avoid misunderstandings caused by directness or indirectness"], "dialogue": [{"speaker": "Dr. Sarnai", "en": "This patient is from abroad and seems confused by my questions.", "mn": "Энэ өвчтөн гадаадаас ирсэн бөгөөд миний асуултад төөрсөн юм шиг байна."}, {"speaker": "Dr. Bold", "en": "Try asking one clear question at a time.", "mn": "Нэг удаад нэг тодорхой асуулт асуугаарай."}, {"speaker": "Dr. Sarnai", "en": "Should I explain things more directly?", "mn": "Би зүйлсийг илүү шууд тайлбарлах хэрэгтэй юу?"}, {"speaker": "Dr. Bold", "en": "Yes, and check understanding often — ''Does that make sense?''", "mn": "Тийм, мөн байнга ойлголтыг шалгаарай — ''Энэ ойлгомжтой байна уу?''"}, {"speaker": "Dr. Sarnai", "en": "What if they don''t understand my accent?", "mn": "Хэрэв тэд миний аялгыг ойлгохгүй бол яах вэ?"}, {"speaker": "Dr. Bold", "en": "Speak a little slower, and use simple words.", "mn": "Бага зэрэг удаан ярьж, энгийн үг хэрэглээрэй."}, {"speaker": "Dr. Sarnai", "en": "That''s helpful advice, thank you.", "mn": "Энэ туслах зөвлөгөө байна, баярлалаа."}], "vocab": [{"en": "culture", "mn": "соёл", "example": "Every culture is different."}, {"en": "misunderstanding", "mn": "буруу ойлголт", "example": "Avoid misunderstandings."}, {"en": "directly / indirectly", "mn": "шууд / шууд бус", "example": "Explain things more directly."}, {"en": "Does that make sense?", "mn": "энэ ойлгомжтой байна уу?", "example": "Does that make sense to you?"}, {"en": "accent", "mn": "аялга", "example": "I have a Mongolian accent."}, {"en": "respectful", "mn": "хүндэтгэлтэй", "example": "Be respectful of differences."}, {"en": "clarify", "mn": "тодруулах", "example": "Let me clarify that."}, {"en": "simple words", "mn": "энгийн үгс", "example": "Use simple words with patients."}, {"en": "patience", "mn": "тэвчээр", "example": "Cross-cultural care needs patience."}, {"en": "international patient", "mn": "олон улсын өвчтөн", "example": "We have more international patients now."}], "grammar": {"title": "Polite clarifying questions", "body": "Use gentle questions to check understanding without embarrassing the patient, and to ask them to clarify without seeming rude.", "examples": ["Does that make sense? → Энэ ойлгомжтой байна уу?", "Could you say that again, please? → Дахин хэлж өгөх боломжтой юу?", "Just to be clear, you mean…? → Тодруулбал, та ... гэсэн үг үү?"]}, "speaking": ["Practice ''Does that make sense?'' after an explanation.", "Describe one way to communicate more clearly with patients.", "Practice ''Could you say that again, please?''", "Give one tip for speaking with an international patient.", "Role-play the full dialogue, both roles."], "quiz": [{"q": "''Does that make ___?'' checks understanding.", "options": ["sense", "sensible", "sensitive", "senseful"], "answer": 0}, {"q": "''Буруу ойлголт'' means…", "options": ["clarification", "misunderstanding", "accent", "patience"], "answer": 1}, {"q": "Could you say that ___, please?", "options": ["again", "more", "yet", "still"], "answer": 0}, {"q": "Use ___ words with international patients.", "options": ["simple", "difficult", "medical only", "long"], "answer": 0}, {"q": "''Тэвчээр'' means…", "options": ["accent", "patience", "culture", "clarity"], "answer": 1}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;

insert into public.course_lessons (week, lesson_no, title, title_mn, video_url, content)
values (30, 1, 'Final Review: Capstone Consultation', 'Эцсийн давтлага: Дүгнэлт үзлэг', 'https://www.youtube.com/watch?v=Z2b-xVdmpII', '{"objectives": ["Review key language from all 30 weeks", "Conduct a full mock consultation confidently", "Combine general and professional English fluently", "Speak with confidence at a strong A2-B1 level"], "dialogue": [{"speaker": "Patient", "en": "Good morning, doctor. I''ve had this pain for a week.", "mn": "Өглөөний мэнд, эмч ээ. Энэ өвдөлт нэг долоо хоног болж байна."}, {"speaker": "Dr. You", "en": "Good morning. On a scale of one to ten, how bad is it?", "mn": "Өглөөний мэнд. Нэгээс арваар үнэлбэл, хэр их вэ?"}, {"speaker": "Patient", "en": "About six. It''s worse when I move.", "mn": "Ойролцоогоор зургаа. Хөдлөхөд илүү өвддөг."}, {"speaker": "Dr. You", "en": "I recommend rest and this medicine, twice a day.", "mn": "Би амралт болон энэ эмийг өдөрт хоёр удаа зөвлөж байна."}, {"speaker": "Patient", "en": "Does my insurance cover this medicine?", "mn": "Миний даатгал энэ эмийг хамардаг уу?"}, {"speaker": "Dr. You", "en": "Yes, it''s covered under your plan. I''ll send a referral if needed.", "mn": "Тийм, таны төлөвлөгөөнд хамрагдана. Шаардлагатай бол шилжүүлэг илгээе."}, {"speaker": "Patient", "en": "Thank you, doctor. That''s very clear.", "mn": "Баярлалаа, эмч ээ. Маш ойлгомжтой байлаа."}], "vocab": [{"en": "review", "mn": "давтах", "example": "Let''s review the key words."}, {"en": "confident", "mn": "итгэлтэй", "example": "I feel confident speaking English now."}, {"en": "consultation", "mn": "үзлэг", "example": "This is a mock consultation."}, {"en": "combine", "mn": "хослуулах", "example": "Combine general and medical English."}, {"en": "fluent / fluently", "mn": "чөлөөтэй / чөлөөтэй ярих", "example": "Speak more fluently every week."}, {"en": "achievement", "mn": "амжилт", "example": "Finishing 30 weeks is a big achievement."}, {"en": "certificate", "mn": "гэрчилгээ", "example": "You will receive a certificate."}, {"en": "continue learning", "mn": "сурч үргэлжлүүлэх", "example": "Continue learning after this course."}, {"en": "proud", "mn": "бахархалтай", "example": "I am proud of my progress."}, {"en": "congratulations", "mn": "баяр хүргэе", "example": "Congratulations on finishing the course!"}], "grammar": {"title": "Review: combining tenses and modals naturally", "body": "A confident speaker mixes present simple, present perfect, going to, should/must, and conditionals naturally within one conversation — exactly like this final consultation.", "examples": ["I''ve had this pain for a week. (present perfect) + I recommend rest. (advice)", "If you take this medicine, you will feel better. (first conditional)", "Does my insurance cover this? + It''s covered under your plan. (insurance English)"]}, "speaking": ["Record a full 90-second mock consultation, both roles.", "Use at least five grammar patterns from the course in one conversation.", "Explain a diagnosis, a prescription, and insurance coverage in one dialogue.", "Say three things you are proud of learning in this course.", "Introduce yourself professionally in English — 60 seconds, no notes."], "quiz": [{"q": "I ___ had this pain for a week.", "options": ["have", "has", "am", "did"], "answer": 0}, {"q": "If you take this medicine, you ___ feel better.", "options": ["will", "would", "are", "do"], "answer": 0}, {"q": "This medicine is ___ under your plan.", "options": ["cover", "covers", "covered", "covering"], "answer": 2}, {"q": "I recommend rest ___ this medicine.", "options": ["and", "but", "or", "so"], "answer": 0}, {"q": "''Амжилт'' means…", "options": ["achievement", "certificate", "confidence", "review"], "answer": 0}]}'::jsonb)
on conflict (week, lesson_no) do update set
  title = excluded.title, title_mn = excluded.title_mn,
  video_url = excluded.video_url, content = excluded.content;
